import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-g-001","clusterId":"G","werkstueckRef":"G.1.1","stufe":1,"question":"Beim Abendessen sagt jemand: „Du glaubst doch alles, was die Medien dir vorsetzen – du bist halt noch ein Schlafschaf, ich bin aufgewacht.“ Was bewirkt diese Wortwahl in der Auseinandersetzung vor allem?","options":["Sie lädt dich freundlich ein, dir selbst ein Bild zu machen, weil sie dich nur als noch nicht informiert beschreibt.","Sie stellt dich als wehrlos Schlafenden und fügsames Herdentier dar, sodass du kaum noch als ernsthafter Gesprächspartner giltst.","Sie zeigt, dass die Person ihre eigene frühere Leichtgläubigkeit selbstkritisch aufarbeitet und andere davor warnen will.","Sie richtet sich vor allem gegen Politik und Verwaltung, die als Hirten auftreten, während die Bevölkerung als unschuldiges Opfer erscheint."],"correctIndex":1,"explanation":"„Schlafschaf“ verbindet zwei Bilder: den unbewussten, wehrlosen Zustand des Schlafs und das blind folgende Schaf. Das Wort wertet ab und entmenschlicht: Wer so genannt wird, gilt nicht mehr als ernstzunehmender Gesprächspartner. Zugleich hebt „aufgewacht“ die eigene Gruppe als überlegen heraus. Der Unterschied wird so nicht als unterschiedliche Bewertung von Belegen dargestellt, sondern als unterschiedlicher „Bewusstseinszustand“. Dann lässt sich jede Kritik als Äußerung eines Schlafenden abtun, und das Gespräch über Belege erübrigt sich. Eine neutrale Einladung ist das nicht, denn gerade die Abwertung ist der Zweck des Wortes.","coreRule":"⚡ Ein Schimpfwort für Andersdenkende ist kein Argument, sondern der Ersatz dafür.","beleg":"Werkstück G.1.1 (Die rhetorische Funktion, Punkt 2: Entmenschlichung der Outgroup)","status":"entwurf","scenario":"","kurz":"Das Wort macht aus einem Meinungsunterschied einen Unterschied im „Bewusstseinszustand“: Wer „schläft“, gilt nicht mehr als ernstzunehmender Gesprächspartner. So lässt sich jede Kritik abtun, ohne über Belege zu reden.","prueffrage":"Welche Belege oder Gründe für seine Sicht nennt der Sprecher, und welche für deine Sicht widerlegt er?","rueckmeldung":[{"option":0,"text":"Ein „noch nicht“ klingt nach Entwicklungsmöglichkeit, doch das Wort lädt zu nichts ein. Es wertet ab, denn wer „schläft“ und wie ein Schaf folgt, soll gar nicht erst als Gegenüber mit eigenen Gründen gelten."},{"option":2,"text":"Im Satz steht keine eigene frühere Leichtgläubigkeit und auch keine Warnung. „Ich bin aufgewacht“ hebt die eigene Seite hervor und das Gegenüber herab, das ist Abwertung statt Selbstkritik."},{"option":3,"text":"Das Hirtenbild liegt nahe, doch der Satz zielt auf die Person am Tisch, nicht auf Politik oder Verwaltung. Als Schaf hingestellt wird hier das Gegenüber: blind folgend und deshalb nicht ernst zu nehmen."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-g-002","clusterId":"G","werkstueckRef":"G.1.1","stufe":2,"question":"Welche Reaktion ist in dieser Lage am sinnvollsten?","scenario":"Du nennst einem Bekannten eine Studie, die seiner Behauptung zu einem Impfstoff widerspricht. Er winkt ab: „Das sagst du nur, weil du noch schläfst.“","options":["Dich gegen das Etikett wehren und betonen, dass du kein Schlafschaf bist, bevor du die Studie genauer erläuterst.","Weitere Studien nachlegen und Quellen verlinken, bis die Beweislast so erdrückend ist, dass er den Inhalt nicht mehr abtun kann.","Das Gespräch beenden, denn wer sich für „erwacht“ hält, ist für Argumente grundsätzlich nicht mehr erreichbar.","Den Rahmen ansprechen statt den Inhalt: Erkenntnis entsteht meist durch langes Zweifeln und Testen, nicht durch ein plötzliches „Erwachen“."],"correctIndex":3,"explanation":"Der Satz „Das sagst du nur, weil du noch schläfst“ wirkt wie ein Schutzschild: Er erklärt jede Kritik im Voraus für wertlos, weil sie angeblich von jemandem kommt, der die Wahrheit nicht sehen kann. Dadurch wird die Ideologie unfalsifizierbar: Kritik von außen kann per Definition ignoriert werden, weil sie ja nur von einem „Schlafenden“ kommt. Wer sich wehrt oder weitere Belege nachlegt, bleibt in diesem Rahmen gefangen, in dem jedes Argument schon vorab abgewertet ist. Das Gespräch zu beenden gibt die Frage auf, statt sie zu klären, und übernimmt selbst die starre Aufteilung in „erwacht“ oder „schlafend“, die ein falsches Dilemma ist. Sinnvoll ist, den Rahmen sichtbar zu machen: Wissenschaftliche Erkenntnis ist meist ein langer Prozess aus Zweifeln, Testen und vorläufiger Annäherung, kein plötzliches „Erwachen“ in eine absolute Wahrheit. Hilfreich ist zudem die Frage, ob das „Aufwachen“ nicht in Wahrheit das Einschlafen in einen einfachen, befriedigenden Traum sein könnte.","coreRule":"⚡ Wenn der Rahmen das Problem ist, hilft es nicht, innerhalb des Rahmens zu antworten.","quote":"Wissenschaftliche Erkenntnis ist meist ein langer, mühsamer Prozess des Zweifelns, des Testens und der langsamen Annäherung an eine vorläufige Wahrheit.","quoteLabel":"Merksatz:","beleg":"Werkstück G.1.1 (Das Anti-Denkmuster; Aktivierungs-Frage)","status":"entwurf","kurz":"Der Satz erklärt jede Kritik vorab für wertlos und macht die Sicht unprüfbar. Deshalb hilft es, den Rahmen selbst anzusprechen: Erkenntnis entsteht meist durch langes Zweifeln und Testen, nicht durch ein plötzliches „Erwachen“.","prueffrage":"Was für eine Antwort oder ein Beleg würde den Bekannten überhaupt noch umstimmen können?","rueckmeldung":[{"option":0,"text":"Sich gegen ein Etikett zu wehren, ist verständlich. Nur lässt sich im Rahmen „du schläfst“ jede Gegenwehr wieder als Beleg für den Schlaf deuten, und die Studie bleibt auch danach vorab abgewertet."},{"option":1,"text":"Weitere Belege sind sachlich gut, hier aber wirkungslos: Wenn jede Kritik schon vorab als Schlafen gilt, wird auch jede neue Quelle so abgetan. Die Wirkung hängt am Rahmen, nicht an der Menge der Belege."},{"option":2,"text":"Das Gespräch zu beenden klärt die Frage nicht, sondern gibt sie auf. Zudem übernimmt die Begründung die Aufteilung in „erwacht“ und „schlafend“, die selbst ein falsches Dilemma ist, und erklärt den Bekannten für unerreichbar."}],"familie":"weltsicht-sichtbar-machen","fertigkeit":"F2"},{"id":"qx-g-003","clusterId":"G","werkstueckRef":"G.1.1","stufe":3,"question":"Was macht das Argument in diesem Gespräch unwiderlegbar, und was ist daran der Denkfehler?","options":["Er erklärt den Unterschied zwischen euch zu einem anderen Bewusstseinszustand statt zu einer anderen Bewertung von Beweisen, sodass jede Kritik von vornherein als wertlos gilt und nichts mehr gegen ihn sprechen kann.","Er erklärt den Unterschied zwischen euch zu einer anderen Bewertung von Beweisen statt zu einem anderen Bewusstseinszustand, sodass jede Kritik von außen mit Gegenbelegen widerlegt werden kann.","Er erklärt den Unterschied zwischen euch zu einem Streit um bloße Wörter statt um Inhalte, sodass jede Kritik von außen sachlich geprüft und beantwortet werden kann.","Er erklärt den Unterschied zwischen euch zu einer vorübergehenden Meinungsverschiedenheit statt zu einem Bewusstseinszustand, sodass jede Kritik von außen ihn jederzeit überzeugen kann."],"correctIndex":0,"explanation":"Jonas macht den Unterschied nicht an der Bewertung von Beweisen fest, sondern an einem angeblich anderen Bewusstseinszustand. Wer „schläft“, kann die Wahrheit per Definition nicht sehen, also darf jeder Einwand ignoriert werden. Damit kann kein denkbarer Einwand und keine denkbare Beobachtung seine Sicht mehr erschüttern. Eine Behauptung, die sich gegen jede mögliche Widerlegung abschirmt, ist unfalsifizierbar und deshalb keine prüfbare Aussage mehr. Typische Signale sind Wörter wie „Schlafschaf“ oder „Systemling“, die Kritiker schon vorab als unwissend abstempeln. Ein sinnvoller Gegenzug ist, nicht um die Etikettierung zu streiten, sondern den Frame selbst zu thematisieren: In der Wissenschaft ist der Weg zur Erkenntnis kein plötzliches „Erwachen“ in eine absolute Wahrheit, sondern ein langer Prozess des Zweifelns, des Testens und der Annäherung an eine vorläufige Wahrheit.","coreRule":"⚡ Wer Kritik schon durch ein Wort als „Schlafen“ abstempelt, macht seine Sicht unwiderlegbar.","quote":"Ein „Schlafschaf“ kann die Wahrheit per Definition nicht sehen.","quoteLabel":"Merksatz:","beleg":"Werkstück G.1.1, Abschnitt 2 (Punkt 3: Epistemologische Immunisierung); keine Fußnote","status":"entwurf","scenario":"In einer Diskussion über ein umstrittenes Thema legt Jonas dir seine Belege vor und sagt: „Dir fehlen die Fakten gar nicht. Du bist einfach noch nicht aufgewacht, du schläfst noch. Deshalb kannst du meine Belege nicht sehen. Und was du dagegen sagst, kommt ja nur von einem Schlafenden.“","kurz":"Jonas macht den Unterschied zu einem Bewusstseinszustand: Wer „schläft“, dessen Einwände zählen nicht. So kann keine Kritik und keine Beobachtung ihn mehr erschüttern, und die Aussage wird unfalsifizierbar. Das ist der Denkfehler.","prueffrage":"Womit begründet Jonas, dass du seine Belege nicht sehen kannst?","rueckmeldung":[{"option":1,"text":"Gegenbelege sind sonst der richtige Weg, um Streit über Beweise zu klären. Hier greifen sie aber nicht, weil Jonas die Differenz gerade nicht als Bewertungsfrage, sondern als anderen Bewusstseinszustand darstellt, in dem Einwände vorab nichts zählen."},{"option":2,"text":"Jonas bringt Belege und bestreitet den Inhalt, ein Wortstreit liegt nicht vor. Eine sachliche Prüfung wäre sonst sinnvoll, doch sein „schläfst noch“ stempelt Kritiker vorab ab und macht diese Prüfung gerade unmöglich."},{"option":3,"text":"Meinungsverschiedenheiten lassen sich normalerweise durch Gründe auflösen. Jonas schließt das aber aus, indem er die Differenz zum Bewusstseinszustand erklärt. Dann kann Kritik ihn gar nicht überzeugen, denn jeder Einwand gilt vorab als wertlos."}],"familie":"immunisierung-erkennen","fertigkeit":"F2"},{"id":"qx-g-004","clusterId":"G","werkstueckRef":"G.1.1","stufe":4,"question":"Welcher Denkfehler steckt in diesem Satz der Führungskraft, obwohl kein Schimpfwort fällt?","scenario":"In einer Firma sagt eine Führungskraft nach der Einführung eines neuen Konzepts: „Wer die Vorteile nicht sieht, ist einfach noch nicht so weit. Das erkennt man erst, wenn man den Sprung gewagt hat.“","options":["Der Satz stützt sich auf die Position der Führungskraft statt auf Argumente, ohne dass ein Gegenargument überhaupt widerlegt würde.","Der Satz ist ein gewöhnliches Werbeversprechen, das Vorteile übertreibt, ohne dass Kritiker dabei in irgendeiner Weise abgewertet würden.","Ein Meinungsunterschied wird zu einem Unterschied im Entwicklungsstand der Person erklärt, sodass Kritik von außen per Definition nichts zählt.","Der Satz bezeichnet Kritiker als dumm und fügsam und spricht ihnen damit ab, überhaupt ernsthafte Gesprächspartner zu sein."],"correctIndex":2,"explanation":"Die Aussage dichtet sich gegen Prüfung ab: Nicht eine unterschiedliche Bewertung der Belege trennt die Lager, sondern ein angeblich anderer Zustand, den man erst nach dem „Sprung“ erreicht. Damit lässt sich jede Kritik abtun („noch nicht so weit“), und kein denkbarer Einwand könnte die Behauptung je widerlegen. Sie ist dann nicht mehr falsifizierbar. Dasselbe Muster steckt in Erweckungs-Rhetorik wie „Aufwachen“ und „Schlafschaf“, nur ohne Schimpfwort. Ob die Vorteile real sind, lässt sich prüfen: mit Belegen, die auch ein Skeptiker nachvollziehen kann, vor dem Sprung statt danach. Die bloße Autorität der Führungskraft oder eine Übertreibung wären ein anderer Fehler, und Beschimpfungen kommen im Satz gar nicht vor.","coreRule":"⚡ Wo Kritik nur noch „nicht so weit“ sein kann, ist eine Behauptung gegen Prüfung abgedichtet.","beleg":"Werkstück G.1.1 (Die rhetorische Funktion, Punkt 3: Epistemologische Immunisierung; Falsifizierbarkeit)","status":"entwurf","kurz":"Der Satz erklärt Kritik zum Zeichen eines anderen Entwicklungsstands („noch nicht so weit“), statt Belege zu prüfen. So kann kein Einwand die Aussage je widerlegen. Der naheliegende Fehler ist, nur nach Beschimpfungen zu suchen.","prueffrage":"Welche Vorteile des Konzepts nennt die Führungskraft konkret, und woran ließen sie sich schon vor dem „Sprung“ prüfen?","rueckmeldung":[{"option":0,"text":"Gegenargumente werden hier tatsächlich nicht widerlegt, sondern übergangen. Die Führungskraft beruft sich aber nicht auf ihr Amt, sondern auf einen angeblichen Entwicklungsstand. Das ist ein anderes Muster als der Verweis auf Autorität."},{"option":1,"text":"Dass Vorteile größer klingen als belegt, wäre ein eigener Fehler. Der Satz tut aber mehr: Er wertet Kritiker ab, indem er sie als „noch nicht so weit“ einordnet. Das Kernproblem liegt darin, dass dadurch jede Kritik von vornherein nichts zählt."},{"option":3,"text":"Eine Herabsetzung der Kritiker steckt tatsächlich im Satz, aber leiser: Von „dumm“ oder „fügsam“ ist nirgends die Rede. Der Fehler liegt nicht in der Wortwahl, sondern darin, dass Kritik als Zustand statt als Einwand behandelt wird."}],"familie":"immunisierung-erkennen","fertigkeit":"F2"},{"id":"qx-g-005","clusterId":"G","werkstueckRef":"G.1.2","stufe":1,"question":"Ein Freund sagt: „Ich vertraue keinen Experten, ich recherchiere lieber selbst. Dazu gehört auch, dass ich mir das, was Fachleute dazu sagen, gar nicht erst anschaue.“ Wo liegt der Kern des Problems an dieser Haltung?","options":["Wer selbst recherchiert, hat Anspruch auf eigene Ergebnisse, und Fachleute sollten dem nicht widersprechen dürfen.","Der Appell zum Selbstdenken klingt nach einer Tugend, wird hier aber so benutzt, dass er Expertenwissen und Gegenargumente abwehrt.","Wer Experten misstraut, liegt zwangsläufig falsch, weil Fachleute in ihrem Gebiet nie irren und deshalb immer recht haben.","Recherche im Internet ist grundsätzlich wertlos, weil dort nur Meinungen und keine Belege zu finden sind und alles beliebig ist."],"correctIndex":1,"explanation":"„Selbst nachdenken“ und „Quellen kritisch prüfen“ sind echte Tugenden und gehören zum Kern des wissenschaftlichen Skeptizismus. Der Satz des Freundes benutzt sie aber als Schutzmauer gegen Expertenwissen und als Freibrief, den wissenschaftlichen Konsens zu ignorieren, und das ist das Gegenteil von kritischem Prüfen. Dazu kommt ein falsches Dilemma („Experten glauben oder selbst denken“): Die dritte Möglichkeit ist, die Glaubwürdigkeit von Experten und Quellen selbst kritisch zu bewerten. Auch der Befund einer US-Panelbefragung aus der Pandemie passt dazu: Wer stärker zustimmte, eigene Recherche sei so viel wert wie das Wissen von Fachleuten, vertraute der Wissenschaft binnen drei Monaten weniger und hielt mehr Falsches über COVID-19 für wahr. Der Zusammenhang war allerdings schwach und stammt aus Befragungsdaten, nicht aus einem Experiment. Die Autoren lesen die Zustimmung zum Slogan eher als Ausdruck einer Haltung gegen Experten denn als Ausdruck sorgfältiger Prüfung, und sie raten vom Selbstrecherchieren nicht ab. Das Problem liegt in der Art, wie es hier eingesetzt wird.","coreRule":"⚡ Je edler ein Slogan klingt, desto genauer lohnt der Blick, was damit in der Praxis gemeint ist: Prüfen heißt auch, die stärksten Gegenargumente zu suchen, nicht sie auszublenden.","beleg":"Werkstück G.1.2 (Die linguistische Autopsie; Die rhetorische Funktion)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Selbst zu denken und Quellen zu prüfen sind echte Tugenden. Hier dienen sie aber als Schutzmauer: Wer Fachleute gar nicht erst anschaut, prüft nicht kritisch, sondern entzieht sich der Prüfung. Eine dritte Möglichkeit wäre, Experten und Quellen selbst zu bewerten.","prueffrage":"Welche Quellen schaut sich dein Freund an, und welche schließt er schon vorab aus?","rueckmeldung":[{"option":0,"text":"Eigene Recherche liefert tatsächlich eigene Ergebnisse, und sie ist an sich nichts Schlechtes. Es geht aber nicht um ein Recht auf Widerspruch, sondern darum, dass der Freund die Gegenargumente gar nicht erst ansieht."},{"option":2,"text":"Auch Fachleute irren manchmal, und Misstrauen kann im Einzelfall berechtigt sein. Falsch liegt der Freund deshalb nicht zwangsläufig; das Problem ist seine Methode, die Fachwissen und Gegenargumente gar nicht erst prüft."},{"option":3,"text":"Im Netz steht tatsächlich viel Unbelegtes, doch eben nicht nur: Es gibt auch Belege und Primärquellen, die man prüfen kann. Selbst zu recherchieren ist deshalb nicht wertlos. Das Problem liegt darin, wie der Freund es einsetzt."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5"},{"id":"qx-g-006","clusterId":"G","werkstueckRef":"G.1.2","stufe":2,"question":"Wie gehst du in diesem Gespräch am besten vor?","scenario":"Eine Kollegin sagt: „Zum Thema Impfen mache ich lieber meine eigene Recherche.“ Du möchtest sie nicht abwerten, aber auch nicht so tun, als sei jede Recherche gleich gut.","options":["Du rätst ab und verweist auf Fachleute, weil Eigenrecherche bei medizinischen Fragen meist in die Irre führt.","Du stimmst zu und fragst nach ihrer Methode, weil gutes Selbstdenken einschließt, die eigene Vorgehensweise zu prüfen.","Du fragst nach ihren Quellen und widerlegst jede einzeln mit einem Faktencheck, weil ihr dann die Grundlage fehlt.","Du stimmst zu und schlägst vor, nur Quellen großer Redaktionen zu nutzen, weil diese am zuverlässigsten sind."],"correctIndex":1,"explanation":"„Selbst nachdenken“ ist ein guter Grundsatz, der aber oft zweckentfremdet wird: als Freibrief, Fachwissen pauschal abzutun. Wer den Appell ablehnt, lässt sich auf ein falsches Dilemma ein („Experten glauben oder selbst denken“) und wirkt abwertend, was Abwehr erzeugt. Die tragfähige dritte Möglichkeit: Selbst denken und dabei die Glaubwürdigkeit von Quellen und Fachleuten kritisch bewerten. Dazu gehört, die eigene Methode zu hinterfragen: Suche ich auch nach den stärksten Gegenargumenten oder nur nach Bestätigung? Das lässt sich als echtes Interesse erfragen, ohne zu belehren. Jede Quelle einzeln zu widerlegen führt zum Streit über Einzelheiten und lässt die Methode unberührt. Nur Quellen großer Redaktionen zu empfehlen umgeht die dritte Option, nämlich die Glaubwürdigkeit von Quellen selbst kritisch bewerten zu lernen. Einordnung: In einer US-Befragung hing Zustimmung zum Slogan „eigene Recherche“ schwach mit mehr Fehlwissen und weniger Vertrauen in die Wissenschaft zusammen. Die Autoren deuten die Zustimmung eher als Ausdruck einer Haltung gegen Experten, nicht als Beleg dafür, dass Selbstrecherche selbst schadet.","coreRule":"⚡ Nimm den Appell zum Selbstdenken ernst und frag nach der Methode.","quote":"Wie stellst du bei deiner ‚eigenen Recherche‘ sicher, dass du nicht einfach nur deinem Bestätigungsfehler erliegst?","quoteLabel":"Eine mögliche Nachfrage:","beleg":"Werkstück G.1.2 (Das Anti-Denkmuster; Aktivierungs-Frage; Falsches Dilemma)","status":"entwurf","kurz":"„Selbst denken“ und „Experten ernst nehmen“ sind kein Gegensatz. Wenn du nach ihrer Methode fragst, ob sie auch die stärksten Gegenargumente sucht, bleibst du respektvoll und lenkst zur Quellenbewertung statt in einen Streit.","prueffrage":"Wie reagiert jemand vermutlich, dessen Vorhaben gleich zu Beginn als falsch oder unzuverlässig hingestellt wird?","rueckmeldung":[{"option":0,"text":"Bei medizinischen Fragen sind Fachleute oft die bessere Quelle, und das Abraten klingt deshalb verantwortungsvoll. Es übernimmt aber das Entweder-oder „Experten glauben oder selbst denken“ und wirkt abwertend, was meist Abwehr auslöst."},{"option":2,"text":"Nach Quellen zu fragen ist gut, und Faktenchecks haben ihren Wert. Wer aber jede Quelle einzeln widerlegt, landet im Streit über Einzelheiten, während die Frage offen bleibt, wie die Kollegin überhaupt sucht und bewertet."},{"option":3,"text":"Etablierte Redaktionen sind oft verlässlicher als beliebige Seiten, und die Zustimmung kommt gut an. Eine feste Quellenliste nimmt ihr aber das Bewerten ab, statt sie darin zu stärken, die Glaubwürdigkeit von Quellen selbst zu beurteilen."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3"},{"id":"qx-g-007","clusterId":"G","werkstueckRef":"G.1.2","stufe":3,"question":"Wie sicher darfst du aus diesem Befund auf Ursache und Wirkung schließen?","options":["Aus dem Befund folgt keine Ursache: Es ist ein schwacher Zusammenhang aus Umfragedaten, und eine Haltung gegen Experten kann beides erklären.","Aus dem Befund folgt eine Ursache: Wer den Slogan teilt, verliert dadurch sein Vertrauen in die Wissenschaft.","Aus dem Befund folgt ein Vorteil: Wer seine Recherche sorgfältig prüft, weiß am Ende mehr über COVID-19 als der Durchschnitt der Befragten.","Aus dem Befund folgt eine Erklärung: Der Slogan erklärt den größten Teil der Falschannahmen, also belegt die Studie schlechte Recherche."],"correctIndex":0,"explanation":"Der Zusammenhang ist schwach: Die Zustimmung zum Slogan erklärt statistisch rund ein Prozent der Unterschiede, der weit größte Teil bleibt offen. Es sind Befragungsdaten, kein Experiment; Ursache und Wirkung lassen sich daraus nicht ablesen. Plausibler ist eine dritte Erklärung: Wer Experten ohnehin misstraut, stimmt dem Slogan eher zu, vertraut der Wissenschaft weniger und glaubt eher Falsches. Genau so deuten die Studienautoren (Chinn und Hasell, 2023) den Befund: Die Zustimmung zum Slogan sei eher Ausdruck einer Haltung gegen Experten. Vom Selbstrecherchieren raten sie nicht ab, sie nennen es „both a prudent and flawed endeavor“. Die anderen Schlüsse behaupten entweder eine Ursache, die die Daten nicht tragen, oder ein Ergebnis, das die Daten nicht zeigen.","coreRule":"⚡ Ein schwacher Zusammenhang in Umfragedaten ist ein Hinweis, kein Beweis für Ursache und Wirkung.","beleg":"Werkstück G.1.2 (Epistemologische Immunisierung); Fn. gl-g-dyor (Chinn/Hasell 2023, S. 1–3 und 6)","status":"entwurf","scenario":"Eine Schlagzeile meldet: „Studie zeigt: Wer ‚eigene Recherche‘ für genauso wertvoll hält wie das Wissen von Fachleuten, glaubt mehr Falsches über COVID-19 und vertraut der Wissenschaft weniger.“ Der Befund stammt aus einer Panelbefragung von US-Erwachsenen (Dezember 2020 und März 2021). Der Zusammenhang war schwach: Die Zustimmung zum Slogan erklärte nur rund 1 Prozent der Unterschiede bei den falschen Annahmen.","kurz":"Aus einem Zusammenhang in Befragungsdaten lässt sich keine Ursache ablesen, erst recht nicht aus einem so schwachen. Der naheliegende Fehler ist, aus „tritt zusammen auf“ ein „führt dazu“ zu machen, obwohl eine Haltung gegen Experten beides erklären kann.","prueffrage":"Wie groß ist der Anteil der Unterschiede, den die Zustimmung zum Slogan statistisch erklärt, und was bleibt übrig?","rueckmeldung":[{"option":1,"text":"Dass beides zusammen auftritt, zeigt die Studie. Warum es so ist, zeigt sie nicht: Befragungsdaten lassen die Richtung offen, und eine Haltung gegen Experten kann Slogan, Misstrauen und Falschannahmen zugleich erklären."},{"option":2,"text":"Ein Vorteil sorgfältiger Recherche lässt sich daraus nicht ablesen. Gemessen wurde nur die Zustimmung zu einem Slogan, nicht, wie jemand tatsächlich recherchiert oder wie gut er das tut."},{"option":3,"text":"Die genannte Zahl spricht dagegen: Der Slogan erklärt nur rund ein Prozent der Unterschiede, der weit größte Teil bleibt offen. Zudem misst die Studie Zustimmung zu einem Satz, nicht die Qualität einer Recherche."}],"familie":"korrelation-und-ursache","fertigkeit":"F2"},{"id":"qx-g-008","clusterId":"G","werkstueckRef":"G.1.2","stufe":4,"question":"Was ist an dieser Abwehr denkerisch fehlerhaft?","scenario":"Du legst einer Kollegin den Befund einer Virologin vor. Sie winkt ab: „Das sagen nur die Eliten, ich denke lieber selbst nach.“ Auf die Frage, was sie am Befund konkret falsch findet, geht sie nicht ein.","options":["Sie verwirft den Befund wegen der Gruppe seiner Urheber („Eliten“) statt wegen seiner Argumente und macht sich so gegen jede Expertenkritik unangreifbar.","Sie prüft den Befund zuerst auf Methodenfehler und lehnt ihn erst danach ab, sodass der Fehler nur in der knappen Formulierung liegt.","Sie beruft sich auf das Recht auf Skepsis, und weil Skepsis immer richtig ist, kann die Abwehr gar nicht fehlerhaft sein.","Sie misstraut einer einzelnen Studie, ohne Experten als Gruppe abzulehnen, sodass die Haltung als gesunde Kritik gelten kann."],"correctIndex":0,"explanation":"Hier liegt ein Ad Hominem vor: Der Befund wird nicht an seinen Argumenten oder Methoden gemessen, sondern pauschal abgelehnt, weil die Urheber zur Gruppe der „Eliten“ zählen. Der Satz wirkt zugleich als Schutzmauer: Jede Kritik von Fachleuten lässt sich mit ihm abwehren, ganz gleich, wie gut sie begründet ist. Das ist ein Freibrief, den wissenschaftlichen Konsens zu ignorieren. Echtes Selbst-Nachdenken heißt dagegen, die eigenen Methoden zu hinterfragen und aktiv die stärksten Gegenargumente zu suchen. Dazu passt eine US-Panelbefragung aus der Pandemie (Chinn und Hasell, 2023): Je stärker Befragte zustimmten, „eigene Recherche“ sei so viel wert wie das Wissen von Fachleuten, desto eher sank binnen drei Monaten ihr Vertrauen in die Wissenschaft und desto mehr Falsches hielten sie über COVID-19 für wahr. Der Zusammenhang war schwach und stammt aus Befragungsdaten, nicht aus einem Experiment.","coreRule":"⚡ Wer die Quelle verwirft statt das Argument, prüft nicht, sondern immunisiert sich.","beleg":"Werkstück G.1.2 (Die rhetorische Funktion, Punkt 2: Epistemologische Immunisierung; Die transportierten Denkfehler: Ad Hominem)","status":"entwurf","kurz":"Der Befund wird nicht an seinen Argumenten gemessen, sondern pauschal verworfen, weil seine Urheber zu den „Eliten“ zählen. So lässt sich jede Fachkritik abwehren, egal wie gut sie begründet ist, und genau das macht die Haltung unangreifbar.","prueffrage":"Welchen einzelnen Punkt des Befunds hat die Kollegin bisher angesprochen?","rueckmeldung":[{"option":1,"text":"Eine Methodenprüfung wäre ein ordentlicher Grund zur Ablehnung. Sie findet hier aber gar nicht statt: Die Kollegin winkt ab und geht auf die Nachfrage nicht ein. Der Fehler liegt in der Begründung, nicht in der Kürze."},{"option":2,"text":"Skepsis ist sinnvoll, wenn sie am Inhalt ansetzt. Immer richtig ist sie nicht, und hier gilt sie nicht den Argumenten, sondern pauschal einer Gruppe. Echtes Selbst-Nachdenken prüft auch die eigenen Methoden und sucht die stärksten Gegenargumente."},{"option":3,"text":"Kritik an einer einzelnen Studie wäre legitim, wenn sie deren Methoden träfe. Die Kollegin begründet ihre Ablehnung aber mit der Gruppe der „Eliten“, nicht mit einem Mangel dieses Befunds, und nennt keinen einzigen inhaltlichen Punkt."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-g-009","clusterId":"G","werkstueckRef":"G.1.3","stufe":1,"question":"Wie würdest du die Aussage dieser Person am treffendsten einordnen?","options":["Sie stellt eine plötzliche Erweckung als Befreiung dar und teilt die Welt in Wissende und Schlafende, ohne Belege zu nennen.","Sie schildert nüchtern den langsamen Prozess, in dem sie neue Belege geprüft und ihre Meinung deshalb geändert hat.","Sie verwendet einen Begriff, der ausschließlich in extremistischen Gruppen gebraucht wird und sonst nirgends vorkommt.","Sie schließt sich bewusst der wissenschaftlichen Mehrheitsmeinung an und nimmt dafür unbequeme Konsequenzen in Kauf."],"correctIndex":0,"explanation":"Die Metapher stammt aus dem Film „The Matrix“: Die rote Pille lässt Neo aus der Simulation erwachen. Als Erzählmuster macht sie aus einer Meinungsänderung einen plötzlichen Moment der Erweckung und teilt die Menschen in „Aufgewachte“ und „Schlafschafe“. Genau das passiert hier: Statt Belege zu nennen, beruft sich die Person auf ihr Erweckungserlebnis. Dem plötzlichen „Red Pill“-Moment steht der langsame, schrittweise Prozess gegenüber, in dem man Belege prüft und neu bewertet. Dass der Begriff nur in extremistischen Gruppen vorkäme, stimmt nicht: Er wird auch in Verschwörungsmythen und als allgemeiner Internet-Slang für jede Erkenntnis gegen den Mainstream gebraucht. Und die Option, sich der wissenschaftlichen Mehrheitsmeinung anzuschließen, passt nicht, weil die Metapher gerade für alternative Weltanschauungen steht, die sich gegen den Mainstream richten.","coreRule":"⚡ „Rote Pille“ erzählt Bekehrung als Erweckung. Wissen entsteht aber durch Prüfen, nicht durch einen einzigen Moment.","beleg":"Werkstück G.1.3 (Die Wahl; Kernidee; Anwendung & Relevanz)","status":"entwurf","scenario":"In einem Forum schreibt jemand: „Ich habe die rote Pille genommen. Seitdem sehe ich, wie die Medien uns alle belügen. Wer mir nicht glaubt, schläft noch.“","kurz":"Die Person ersetzt Belege durch ein Erweckungserlebnis und teilt andere in Wissende und Schlafende. Wer so erzählt, macht aus einer Meinungsänderung einen plötzlichen Moment, statt zu zeigen, welche Belege sie bewegt haben.","prueffrage":"Welche überprüfbare Angabe macht die Person, außer dass sie jetzt „sieht“, was andere nicht sehen?","rueckmeldung":[{"option":1,"text":"Eine Meinungsänderung nach geprüften Belegen wäre völlig in Ordnung. Hier steht davon aber nichts: Die Person nennt weder Belege noch einen Prozess, sondern einen Moment, seit dem sie die Medien zu durchschauen glaubt."},{"option":2,"text":"Dass der Begriff in extremistischen Kreisen vorkommt, stimmt. Auf sie beschränkt ist er aber nicht: Er taucht auch in Verschwörungsmythen und als Internet-Slang für jede Erkenntnis gegen den Mainstream auf."},{"option":3,"text":"Sich der Mehrheitsmeinung anzuschließen kann unbequem sein. Die Aussage der Person geht aber in die Gegenrichtung: Die Bildsprache steht für Weltsichten gegen den Mainstream, und von Wissenschaft ist im Beitrag keine Rede."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3"},{"id":"qx-g-010","clusterId":"G","werkstueckRef":"G.1.3","stufe":2,"question":"Welche Antwort hilft dir am besten, die Behauptung deines Freundes zu prüfen, statt sie nur anzunehmen oder abzuwehren?","scenario":"Ein Freund schreibt dir: „Du musst die rote Pille nehmen und die Wahrheit über X erkennen! Die offiziellen Stellen wollen nicht, dass du das weißt.“ Er beschreibt seine eigene Erkenntnis als plötzlichen „Aha-Moment“, nach dem für ihn alles klar war.","options":["„Ich nehme lieber die blaue Pille, denn ein angenehmes Weltbild ist im Alltag mehr wert als eine schmerzhafte Wahrheit.“","„Vielleicht stimmen beide Sichtweisen auf ihre Art, dann schauen wir, welche Wahrheit besser zu uns passt.“","„Das ist nur ein Filmbild ohne Bezug zur Wirklichkeit, darauf gehe ich nicht weiter ein.“","„Woher weißt du, dass deine Pille nicht von jemandem stammt, der dir eine bestimmte ‚Wahrheit‘ zeigen will?“"],"correctIndex":3,"explanation":"Die Behauptung ist so gebaut, dass es nur zwei Wege zu geben scheint: schlucken oder in der Täuschung bleiben. Das ist ein falsches Dilemma. Die beste Antwort sprengt dieses Schema, indem sie nach Quelle und Methode fragt: Wer hat die „Erkenntnis“ hergestellt, mit welchem Interesse, und wie wurde sie geprüft? So wird aus einem Befreiungsmoment eine prüfbare Behauptung. Die blaue Pille zu wählen oder beide gleichwertig gelten zu lassen, bleibt innerhalb des Pillen-Schemas und prüft nichts; auch Ausweichen mit dem Hinweis auf ein bloßes Filmbild beantwortet die Frage nicht, wie man Behauptungen dieser Art prüft. Wahre Befreiung liegt nicht im Schlucken einer Pille, sondern darin, die Inhaltsstoffe jeder Pille selbst analysieren zu können.","coreRule":"⚡ Dreh die Pille um: Entscheidend ist nicht ihre Farbe, sondern wer sie hergestellt hat und wie du sie prüfst.","beleg":"Werkstück G.1.3 (Werkbank-Frage; Verbindungen: Falsches Dilemma)","status":"entwurf","kurz":"Wer fragt, woher die „Erkenntnis“ stammt, wer sie hergestellt hat und wie sie geprüft wurde, macht aus dem Befreiungsmoment eine prüfbare Behauptung. Der Denkfehler ist, die Pillenwahl für alternativlos zu halten, obwohl es einen dritten Weg gibt.","prueffrage":"Welche überprüfbaren Angaben zu X enthält die Nachricht deines Freundes außer dem Bild von der Pille?","rueckmeldung":[{"option":0,"text":"Ein angenehmes Weltbild zu wählen, ist ebenso wenig eine Prüfung wie das Schlucken der roten Pille. Ob etwas stimmt, hängt nicht davon ab, wie gut es sich anfühlt, und du bleibst im Zwei-Wege-Schema des Freundes."},{"option":1,"text":"Verschiedene Sichtweisen können tatsächlich Teilwahrheiten enthalten. Hier läuft der Satz aber auf bloße Gleichstellung hinaus, und was „zu uns passt“, sagt nichts darüber, wer die Behauptung aufgestellt hat und wie sie belegt ist."},{"option":2,"text":"Die Pille ist wirklich nur ein Bild aus einem Film. Der Freund meint damit aber etwas Konkretes, nämlich dass Stellen etwas verschweigen. Wer nur das Bild abtut, lässt diese Behauptung unbeantwortet und ungeprüft."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3"},{"id":"qx-g-011","clusterId":"G","werkstueckRef":"G.1.3","stufe":3,"question":"Eine Kollegin sagt im Gespräch: „Das war für mich echt eine rote Pille.“ Im Netz behauptet jemand: „Wer die blaue Pille schluckt, will die Wahrheit nicht sehen – deshalb ist jede Studie, die mir widerspricht, Teil der Matrix.“ Woran erkennst du, dass die Metapher im zweiten Fall zum Problem wird?","options":["Der Beitrag erklärt die Metapher zur einzigen Realität und lehnt dadurch jede Prüfung durch Belege, Studien und Gegenargumente im Voraus ab.","Der Beitrag verwendet überhaupt eine Filmmetapher, und schon der Rückgriff auf ein solches Bild zeigt, dass sein Urheber einer alternativen Ideologie anhängt.","Der Beitrag überträgt ein Bild aus einem Film auf eine reale Debatte, und solche Übertragungen sind grundsätzlich unzulässig, weil sie Wirklichkeit und Fiktion vermischen.","Der Beitrag findet im Netz viele Leser, und sobald eine Metapher sehr weit verbreitet ist, verliert sie ihre ursprüngliche Bedeutung und wird dadurch gefährlich."],"correctIndex":0,"explanation":"Eine Metapher zu benutzen ist für sich genommen harmlos; auch die Kollegin nutzt dasselbe Bild, ohne dass etwas schiefläuft. Problematisch wird es, wenn das Bild zur einzigen Realität erklärt wird und damit jede Information, die widerspricht, schon im Voraus als Täuschung gilt. Dann ist die Aussage gegen Belege immunisiert, und Argumente können sie nicht mehr erreichen. Entscheidend ist also nicht das Wort und auch nicht, wie viele es verwenden, sondern ob im Namen des Bildes auf jede Prüfung verzichtet wird.","coreRule":"⚡ Nicht die Metapher ist das Problem, sondern der Verzicht auf jede Prüfung im Namen der Metapher.","quote":"","quoteLabel":"","beleg":"Werkstück G.1.3 (Der Kipppunkt)","status":"entwurf","scenario":"Zwei Aussagen im Vergleich: Die Kollegin beschreibt eine Erkenntnis mit einem Filmbild. Der Netzbeitrag verwendet dasselbe Bild, um jede widersprechende Quelle von vornherein auszuschließen.","kurz":"Das Bild selbst ist harmlos, die Kollegin nutzt es ja auch. Problematisch wird es erst, wenn es zur einzigen Realität erklärt wird: Dann gilt jede Gegeninformation vorab als Täuschung, und Belege können die Aussage nicht mehr erreichen.","prueffrage":"Welche Folgen zieht die Kollegin aus ihrem Bild, und welche zieht der Netzbeitrag daraus?","rueckmeldung":[{"option":1,"text":"Ein Filmbild verrät noch nichts über die Weltanschauung dessen, der es benutzt, denn die Kollegin verwendet dasselbe. Dass mit diesem Beitrag etwas nicht stimmt, ist richtig, aber es liegt nicht am Bild, sondern daran, wie es eingesetzt wird."},{"option":2,"text":"Bilder aus Filmen dürfen reale Debatten veranschaulichen, das tut die Kollegin auch. Fiktion und Wirklichkeit verschwimmen hier erst, weil das Bild wörtlich genommen und gegen jede Prüfung gesetzt wird, nicht durch die Übertragung an sich."},{"option":3,"text":"Wie viele ein Bild verwenden, sagt nichts darüber, ob es einer Prüfung standhält oder sie verhindert. Gefährlich wird es nicht durch Verbreitung, sondern dadurch, dass im Namen des Bildes jedes Gegenargument im Voraus abgewiesen wird."}],"familie":"nach-weg-und-kriterium-fragen","fertigkeit":"F3"},{"id":"qx-g-012","clusterId":"G","werkstueckRef":"G.1.4","stufe":1,"question":"Welche Frage prüft am besten, ob der Slogan „Mein Körper, meine Wahl“ in dieser Situation ein tragfähiges Argument ist?","options":["Betrifft die Entscheidung nur den eigenen Körper, oder setzt sie auch andere einem vorhersehbaren Risiko aus?","Wie häufig wird der Slogan heute in öffentlichen Debatten verwendet, und von wem?","Wie bekannt und angesehen ist die Bewegung, aus der der Slogan ursprünglich stammt?","Wie überzeugt ist der Bürger selbst von seiner Entscheidung, und wie lange vertritt er sie schon?"],"correctIndex":0,"explanation":"Ein Slogan trägt nur dann, wenn seine Voraussetzung auch im neuen Zusammenhang gilt. Der Satz „Mein Körper, meine Wahl“ ist stark, wo eine Entscheidung wirklich nur den eigenen Körper betrifft. Bei einer ansteckenden Krankheit trifft das nicht rein zu, weil die Entscheidung Folgen für andere hat (Ansteckungsrisiko), etwa für Menschen mit geschwächtem Immunsystem. Das Ansehen des Slogans, seine Verbreitung oder die Überzeugung des Sprechers sagen darüber nichts aus. Auch eine geliehene moralische Aura ersetzt keine Begründung, denn sie macht den Satz nicht passender für den neuen Fall. Der Kern der Prüfung ist deshalb, ob die Voraussetzung des Slogans hier erfüllt ist: Berührt die Wahl nur mich, oder auch andere?","coreRule":"⚡ Geliehene Moral ersetzt kein Argument: Prüfe, ob die Voraussetzung des Slogans im neuen Zusammenhang erfüllt ist.","beleg":"Werkstück G.1.4 (Kontext & Tiefe, Punkt 1: Er kapert die moralische Hoheit)","status":"entwurf","scenario":"In einer Debatte über eine Impfpflicht während einer Pandemie legt eine Wissenschaftlerin Daten zur Ansteckung und zum Schutz Dritter vor. Ein Bürger antwortet nur: „Mein Körper, meine Wahl.“ Der Satz stammt ursprünglich aus dem Kampf um das Recht auf Entscheidungen über den eigenen Körper und hat dort hohe moralische Überzeugungskraft.","kurz":"Der Slogan trägt nur, wenn die Entscheidung wirklich allein den eigenen Körper betrifft. Bei einer ansteckenden Krankheit wirkt sie auch auf andere. Die Aura der Herkunft ersetzt keine Begründung für den neuen Fall.","prueffrage":"Was zeigen die Daten der Wissenschaftlerin, und auf welchen ihrer Punkte geht der Bürger mit seinem Satz ein?","rueckmeldung":[{"option":1,"text":"Wie oft und von wem der Slogan gerufen wird, zeigt seine Reichweite. Ob seine Voraussetzung im konkreten Fall erfüllt ist, lässt sich daraus nicht ablesen, denn ein verbreiteter Satz kann trotzdem schlecht passen."},{"option":2,"text":"Das hohe Ansehen der Bewegung erklärt, warum der Satz so stark klingt. Gerade diese geliehene Aura ersetzt aber keine Begründung. Dort stimmte die Voraussetzung, hier ist offen, ob sie gilt."},{"option":3,"text":"Der Bürger kann seine Haltung ehrlich und seit Langem vertreten. Wie sicher sich jemand ist, sagt aber nichts darüber, ob sein Argument trägt, denn auch feste Überzeugungen können auf einer unpassenden Voraussetzung beruhen."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3"},{"id":"qx-g-013","clusterId":"G","werkstueckRef":"G.1.4","stufe":2,"question":"Welche Erwiderung hält das Gespräch am ehesten offen und führt zum eigentlichen Streitpunkt?","scenario":"Du fragst in einer Diskussion über Ansteckungsschutz: „Aber was ist mit den immungeschwächten Menschen, die du ansteckst?“ Dein Gegenüber antwortet nur: „Mein Körper, meine Wahl.“ Du willst das Gespräch weiterführen, statt dass es hier endet.","options":["Du bestreitest das Recht im Kern: In einer Pandemie gibt es keine Selbstbestimmung über den eigenen Körper mehr.","Du widerlegst die Wahl mit Zahlen zur Viruslast und Übertragbarkeit, bis sie dem Gegenüber unvernünftig erscheint.","Du hältst dem Gegenüber vor, dass es den Slogan bei Abtreibung oder Drogenkonsum ablehnt, und stellst so seine Glaubwürdigkeit infrage.","Du stimmst dem Recht zu und zeigst den Konflikt: Selbstbestimmung ist ein hohes Gut, steht hier aber gegen das Recht anderer auf körperliche Unversehrtheit."],"correctIndex":3,"explanation":"Am besten greifst du das Recht nicht an, sondern stimmst ihm zu und zeigst den Konflikt auf. Wer das Recht selbst bestreitet, verlässt diesen Rahmen und stellt etwas Legitimes infrage. Außerdem stimmt die Aussage nicht: Das Recht auf Selbstbestimmung gilt weiter, es hat aber Grenzen, wo es auf die Rechte anderer trifft. Der Slogan wirkt zudem wie ein Schild, an dem jede Evidenz abprallt. Eine datenreiche Widerlegung verfehlt deshalb den Kern, denn der Streitpunkt ist der Rechtekonflikt, nicht die Faktenlage. Die Inkonsistenz bei Abtreibung oder Drogenkonsum ist eine Red Flag zur Erkennung des Missbrauchs, aber keine Gesprächsstrategie. Sie klärt außerdem nicht, ob die Entscheidung andere gefährdet. Die Erwiderung, die zustimmt und den Konflikt zweier berechtigter Ansprüche benennt, erweitert den Rahmen. Aus einem Totschlagargument wird so eine Abwägung, über die man reden kann.","coreRule":"⚡ Greif das Recht nicht an: Stimm ihm zu und zeig, wo es auf ein anderes Recht trifft.","quote":"","quoteLabel":"","beleg":"Werkstück G.1.4 (Das Anti-Denkmuster, Skript 1: Der Rechte-Konflikt; Red Flags)","status":"entwurf","kurz":"Am besten stimmst du dem Recht auf Selbstbestimmung zu und zeigst, dass es hier auf das Recht anderer auf Unversehrtheit trifft. So wird aus dem Totschlagargument eine Abwägung, über die man reden kann, statt das Recht selbst zu bestreiten.","prueffrage":"Welche Erwiderung würde dein Gegenüber vermutlich als Angriff auf sich selbst verstehen, und welche nicht?","rueckmeldung":[{"option":0,"text":"Die Sorge um andere ist berechtigt. Aber das Recht auf Selbstbestimmung gilt weiter, es hat nur dort Grenzen, wo es auf die Rechte anderer trifft. Wer es im Kern bestreitet, stellt etwas Legitimes infrage und verlässt den Rahmen des Gesprächs."},{"option":1,"text":"Fakten zur Gefährdung sind wichtig, doch der Streitpunkt liegt woanders: Hier stehen zwei Rechte gegeneinander, nicht widersprüchliche Daten. Der Slogan wirkt wie ein Schild, an dem Zahlen abprallen, und das Gespräch kommt nicht weiter."},{"option":2,"text":"Eine solche Inkonsistenz kann ein Warnzeichen sein, dass der Slogan nur als Schutzschild dient. Als Gesprächszug wirkt sie aber wie ein Angriff auf die Glaubwürdigkeit, führt vom Thema weg und klärt nicht, ob die Entscheidung andere gefährdet."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3"},{"id":"qx-g-014","clusterId":"G","werkstueckRef":"G.1.4","stufe":3,"question":"Sophie sagt in einer Diskussion über eine Impfung während einer Pandemie: „Ob ich mich impfen lasse, ist meine Privatsache, so wie die Entscheidung für ein Tattoo.“ Was ist an dieser Gleichsetzung der Fehler?","options":["Eine Impfentscheidung kann das Ansteckungsrisiko anderer verändern, und wenn viele gleich entscheiden, kann das Gesundheitssystem überlastet werden.","Bei Gesundheitsfragen hat der Staat immer Vorrang, sodass das Recht auf körperliche Selbstbestimmung dort grundsätzlich nicht gilt.","Medizinisch notwendige Eingriffe dürfen in keinem Fall abgelehnt werden, ein Tattoo dagegen ist freiwillig und deshalb frei wählbar.","Die Gemeinschaft bezahlt den Impfstoff und kann deshalb als Gegenleistung die Teilnahme des Einzelnen verlangen."],"correctIndex":0,"explanation":"Eine Tätowierung ist eine rein private Wahl. Eine Impfentscheidung in einer Pandemie kann dagegen das Ansteckungsrisiko anderer verändern, vor allem für immungeschwächte Menschen, je nachdem, wie gut der Impfstoff auch vor Übertragung schützt. Fachlich spricht man hier von einer „Externalität“. Dazu kommt eine Konsequenz zweiter Ordnung: Treffen viele Menschen dieselbe Entscheidung, kann das Gesundheitssystem überlastet werden. Das Recht auf körperliche Selbstbestimmung bleibt davon unberührt. Wer etwa eine empfohlene Operation ablehnt, entscheidet legitim, weil es dabei um den Schutz des eigenen Körpers vor einem Eingriff geht. Der Fehler in Sophies Aussage liegt also nicht darin, dieses Recht zu betonen, sondern darin, eine Handlung mit Folgen für Dritte wie eine rein private Handlung zu behandeln.","coreRule":"⚡ Eine Wahl mit Folgen für Dritte ist keine rein private Wahl mehr.","beleg":"Werkstück G.1.4 (Kontext & Tiefe, Punkt 3; Der Kipppunkt; Anti-Denkmuster, Skript 2)","status":"entwurf","scenario":"","kurz":"Ein Tattoo betrifft nur die eigene Haut, eine Impfung in der Pandemie kann auch das Ansteckungsrisiko anderer verändern. Der Fehler liegt nicht darin, Selbstbestimmung zu betonen, sondern darin, eine Handlung mit Folgen für Dritte wie eine rein private zu behandeln.","prueffrage":"Darf man eine ärztlich empfohlene Operation ablehnen, und was unterscheidet diese Entscheidung von Sophies Impfentscheidung?","rueckmeldung":[{"option":1,"text":"Gesundheit geht oft auch andere an, daher wirkt ein Vorrang des Staates einleuchtend. Doch „immer“ und „grundsätzlich nicht“ gehen zu weit: Das Recht auf Selbstbestimmung bleibt bestehen, und Sophies Fehler liegt nicht darin, es zu betonen."},{"option":2,"text":"Notwendig gegen freiwillig wirkt wie ein klares Kriterium. „In keinem Fall“ ist jedoch zu absolut: Eine empfohlene Operation darf man legitim ablehnen. Entscheidend ist nicht die Notwendigkeit, sondern ob die Entscheidung andere betrifft."},{"option":3,"text":"Wer zahlt, hat scheinbar ein Mitspracherecht. Aus der Finanzierung folgt aber keine Pflicht zur Teilnahme, und sie trifft den Punkt nicht: Der Unterschied zum Tattoo liegt in den Folgen für andere, nicht in der Frage, wer die Kosten trägt."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3"},{"id":"qx-g-015","clusterId":"G","werkstueckRef":"G.1.4","stufe":4,"question":"Was trägt an dieser Berufung auf Selbstbestimmung nicht?","scenario":"Eltern sagen: „Es ist meine Entscheidung, meinem Kind bei Krebs nur Globuli zu geben. Das ist meine Selbstbestimmung.“","options":["Nichts: Das Recht auf Selbstbestimmung ist absolut und schließt Entscheidungen über das eigene Kind selbstverständlich ein.","Globuli sind teurer als wirksame Behandlungen, und Eltern dürfen sich nicht für teure Mittel entscheiden.","Es geht nicht um den eigenen Körper, sondern um den eines anderen Menschen; hier stößt das Recht der Eltern an die Fürsorgepflicht für das Kind.","Die Berufung ist nur dann problematisch, wenn die Eltern zugleich Impfungen ablehnen; für sich genommen ist sie unproblematisch."],"correctIndex":2,"explanation":"Körperliche Selbstbestimmung schützt Menschen davor, dass andere über ihren Körper verfügen. Sie gilt für den eigenen Körper. Hier entscheiden die Eltern aber über die Behandlung eines anderen Menschen, und zwar für eine wirkungslose Therapie. Dabei kollidiert das Recht des Individuums mit der Fürsorgepflicht für andere. Ein Recht als absolut hinzustellen, ohne seine Grenzen und die Rechte anderer anzuerkennen, ist ein Anzeichen für rhetorischen Missbrauch der Selbstbestimmung. Die Kosten der Mittel spielen für diese Prüfung keine Rolle, und ob die Eltern auch Impfungen ablehnen, ändert nichts daran, dass hier über den Körper eines anderen entschieden wird.","coreRule":"⚡ Selbstbestimmung gilt für den eigenen Körper; bei Entscheidungen für andere tritt die Fürsorgepflicht hinzu.","beleg":"Werkstück G.1.4 (Anwendung & Relevanz: Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Selbstbestimmung schützt davor, dass andere über den eigenen Körper verfügen. Hier entscheiden die Eltern aber über den Körper eines anderen Menschen, und zwar für eine wirkungslose Therapie. Das Recht stößt an die Fürsorgepflicht für das Kind.","prueffrage":"Was geschieht vermutlich mit der Krebserkrankung, wenn sie nur mit Globuli behandelt wird?","rueckmeldung":[{"option":0,"text":"Selbstbestimmung ist ein hohes Gut, und Eltern haben viel Entscheidungsspielraum. Kein Recht gilt aber grenzenlos, und dieses schützt den eigenen Körper. Hier geht es um den Körper des Kindes, dessen Wohl die Fürsorgepflicht der Eltern schützt."},{"option":1,"text":"Der Preis wirkt wie ein handfestes Argument, spielt hier aber keine Rolle; auch ein billiges Mittel änderte nichts. Der Einwand liegt darin, dass die Eltern über den Körper eines anderen Menschen entscheiden."},{"option":3,"text":"Mit Impfablehnung hat der Fall nichts zu tun, und sie änderte auch nichts. Schon für sich genommen trägt die Berufung nicht, weil über den Körper eines anderen Menschen entschieden wird und die Fürsorgepflicht Grenzen setzt."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3"},{"id":"qx-g-016","clusterId":"G","werkstueckRef":"G.2.1","stufe":1,"question":"In einer Diskussion sagt jemand: „Dass die Wirtschaft so schlecht läuft, liegt an den Eliten. Die steuern im Hintergrund alles, Politik, Konzerne und Medien. Wenn ein Politiker sich als unschuldig erweist, war er eben nur eine Marionette der wahren Elite.“ Was ist an dieser Argumentation das Kernproblem?","options":["Die Behauptung ist so gebaut, dass sie nie widerlegt werden kann: Die „Eliten“ bleiben undefiniert, und jeder entlastete Politiker gilt als Marionette der wahren Elite.","Die Behauptung ist so gebaut, dass sie nur stimmen kann, wenn Politiker und Konzernchefs tatsächlich zusammenarbeiten, was bisher niemand belegen konnte.","Die Behauptung ist so gebaut, dass sie Menschen mit viel Einfluss kritisiert, was in einer Demokratie grundsätzlich unzulässig und deshalb falsch ist.","Die Behauptung ist so gebaut, dass sie die Wirtschaftslage zu negativ darstellt, weil Krisen meist mehrere Ursachen haben und nie nur eine."],"correctIndex":0,"explanation":"Das Argument ist durch Vagheit gegen Widerlegung abgeschirmt: Da nie genau definiert wird, wer „die Eliten“ sind, kann die Behauptung nie widerlegt werden. Erweist sich ein Beschuldigter als unschuldig, war er eben nur eine Marionette der „wahren Elite“ dahinter. Der Feind ist wie ein Nebel, man kann ihn nicht festnageln. Wer eine solche Behauptung ernsthaft prüfen will, braucht deshalb Präzision: konkrete Namen und überprüfbare Belege dafür, dass sich diese Personen abgesprochen haben. Außerdem wird aus Menschen in Machtpositionen eine einzige, geheime und bösartige Kabale gemacht. Dass Krisen oft mehrere Ursachen haben, stimmt zwar, trifft aber nicht den Kern: Der Fehler liegt in der Struktur der Behauptung, nicht in ihrem Thema.","coreRule":"⚡ Wer „die Eliten“ sagt, ohne Namen und Belege zu nennen, baut eine Behauptung, die sich nicht widerlegen lässt. Frag deshalb nach konkreten Personen und überprüfbaren Absprachen.","beleg":"Werkstück G.2.1 (Die linguistische Autopsie)","status":"entwurf","scenario":"","kurz":"Die Behauptung lässt sich nie widerlegen: Wer die „Eliten“ sind, bleibt offen, und selbst ein entlasteter Politiker wird zur Marionette der „wahren Elite“ erklärt. Eine Behauptung, die jedes Gegenbeispiel in Bestätigung umdeutet, sagt am Ende nichts Prüfbares.","prueffrage":"Was bleibt von der Behauptung übrig, wenn sich ein beschuldigter Politiker als unschuldig erweist?","rueckmeldung":[{"option":1,"text":"Belege für Absprachen wären tatsächlich nötig, wenn man die Behauptung ernsthaft prüfen will. Das eigentliche Problem liegt aber früher: Die Behauptung ist so gebaut, dass sie sich jeder Prüfung entzieht, ob es solche Belege gibt oder nicht."},{"option":2,"text":"Kritik an Menschen mit viel Einfluss gehört in einer Demokratie dazu und ist nicht das Problem. Fragwürdig ist die Bauweise der Behauptung: Sie bleibt vage und deutet jede Entlastung zur Bestätigung um."},{"option":3,"text":"Dass Krisen oft mehrere Ursachen haben, stimmt und spricht gegen einfache Erklärungen. Es trifft aber nicht den Kern: Der Fehler steckt in der Struktur der Behauptung, nicht darin, wie negativ sie die Wirtschaftslage darstellt."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3"},{"id":"qx-g-017","clusterId":"G","werkstueckRef":"G.2.1","stufe":2,"question":"Was ist an dieser Behauptung das zentrale Problem, und welche Rückfrage prüft sie am besten?","scenario":"In einer Diskussion sagt jemand: „Die Eliten haben die Krise geplant.“ Auf Nachfrage, wer das sei, antwortet er: „Na, die da oben eben, die halten alle zusammen.“ Als einzelne Politiker oder Konzernchefs genannt werden, die nachweislich nichts abgesprochen haben, sagt er: „Die waren doch nur Marionetten der wahren Elite dahinter.“","options":["Die Behauptung ist nur Meinung und daher nicht zu beantworten. Am besten fragst du nach den Gefühlen, die dahinterstehen.","Die Behauptung bleibt unwiderlegbar, weil „die Eliten“ nie festgelegt werden. Am besten fragst du, wer konkret dazugehört und welchen überprüfbaren Beleg es für ihre Absprache gibt.","Die Behauptung ist falsch, weil Mächtige grundsätzlich nie koordiniert handeln. Am besten fragst du nach Beispielen für Fehlentscheidungen einzelner Mächtiger.","Die Behauptung ist verdächtig, weil sie Kritik an Mächtigen äußert. Am besten fragst du, warum der Sprecher unbedingt Mächtige kritisieren will."],"correctIndex":1,"explanation":"Der Begriff „die Eliten“ wird nie definiert, und jeder Gegenbeweis wird mit „Marionette der wahren Elite“ aufgefangen. Eine Behauptung, die durch keinen denkbaren Fall widerlegt werden kann, sagt nichts Überprüfbares über die Welt. Die Rückfrage nach konkreten Personen, einem konkreten Ziel und einem Beleg für die Absprache macht aus der Stimmung eine prüfbare Aussage. Sie bestreitet nicht, dass es einflussreiche Gruppen gibt oder dass Mächtige kritisiert werden dürfen. Sie zeigt nur, ob die Behauptung etwas Festes enthält, das man testen kann.","coreRule":"⚡ Wer „die Eliten“ sagt, soll Namen, Ziel und Beleg nennen können. Eine Behauptung, die jeden Gegenbeweis einbaut, ist unprüfbar.","quote":"Kannst du bitte präzise sein? Wer genau gehört zu diesen ‚Eliten‘? Nenne bitte fünf Namen.","quoteLabel":"Merksatz:","beleg":"Werkstück G.2.1 (Das Anti-Denkmuster; Aktivierungs-Frage)","status":"entwurf","kurz":"Die Behauptung lässt sich durch keinen denkbaren Fall widerlegen, weil „die Eliten“ nie festgelegt werden und jeder Gegenbeweis zur „Marionette“ erklärt wird. Erst die Rückfrage nach Personen, Ziel und Beleg macht aus der Stimmung eine prüfbare Aussage.","prueffrage":"Was ändert sich an der Behauptung, nachdem Politiker genannt wurden, die nachweislich nichts abgesprochen haben?","rueckmeldung":[{"option":0,"text":"Hinter solchen Sätzen stehen oft echte Gefühle, doch der Satz behauptet etwas über die Welt: dass bestimmte Leute die Krise geplant haben. Prüfbar wird das, sobald feststeht, wer gemeint ist; die Frage nach Gefühlen führt daran vorbei."},{"option":2,"text":"Mächtige stimmen sich durchaus manchmal ab, etwa in Kartellen; „grundsätzlich nie“ ist selbst eine unbelegte Pauschale. Beispiele für Fehlentscheidungen prüfen keine Absprache. Das Problem ist, dass nie festgelegt wird, wer „die Eliten“ sind."},{"option":3,"text":"Kritik an Mächtigen ist legitim und kein Grund für Verdacht. Und die Frage nach den Motiven des Sprechers sagt nichts darüber, ob seine Aussage stimmt. Geprüft wird, was behauptet wird, nicht wer es sagt."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3"},{"id":"qx-g-018","clusterId":"G","werkstueckRef":"G.2.1","stufe":3,"question":"Wie solltest du den Beitrag und den Streit der beiden Leser am besten beurteilen?","scenario":"In einem Online-Beitrag wird mehrfach „Globalisten“ als Schuldiger für Wirtschaftskrise, Pandemie und Kriege genannt. Wer damit gemeint ist, bleibt offen, und Juden werden nirgends erwähnt. Eine Leserin schreibt darunter: „Das ist doch klar antisemitisch!“ Ein anderer Leser antwortet: „Das Wort ist völlig neutral, du unterstellst da etwas.“","options":["Das Wort gilt in solchen Zusammenhängen als bekannter antisemitischer Code. Ob es hier so gemeint ist, zeigt erst der Kontext: wer genau gemeint ist und welche Belege es gibt.","Das Wort gilt in solchen Zusammenhängen als bekannter antisemitischer Code. Damit ist belegt, dass der Verfasser Juden hasst, eine Prüfung des Textes erübrigt sich.","Ohne ausdrückliche Nennung von Juden kann der Beitrag nicht antisemitisch sein. Wer das behauptet, unterstellt dem Verfasser Absichten, die im Text nicht stehen.","Das Wort bezeichnet schlicht international handelnde Akteure. Wer darin eine versteckte Botschaft vermutet, nutzt einen Kampfbegriff, der keine Prüfung verdient."],"correctIndex":0,"explanation":"Beide Leser machen denselben Fehler: Sie entscheiden, bevor sie geprüft haben. Das Wort „Globalisten“ ist vage; wer damit gemeint ist, bleibt offen, und gerade diese Vagheit macht es unwiderlegbar und vielseitig einsetzbar. In verschwörungsfantastischen Zusammenhängen wird es in der Fachliteratur (Weiß 2024) als bekannter Code geführt, der an die alte antisemitische Erzählung von einer weltbeherrschenden Finanzmacht anknüpft, ohne Juden zu nennen. Das gibt dem Sprecher plausible Abstreitbarkeit. Chapelan (2024) hält zugleich fest, dass Verschwörungserzählungen ohne jüdischen Bezug nicht per se antisemitisch sind. Aus dem Wort allein folgt also weder ein sicherer Beleg für antisemitische Absicht noch das Gegenteil; man prüft Kontext und Belege. Die gute Prüfung fragt: Wer genau ist gemeint, und welcher Beleg stützt die Schuldzuweisung?","coreRule":"⚡ Entscheide bei einem vagen Reizwort nicht aus dem Bauch, sondern prüfe den Kontext: Welche Gruppe ist gemeint, welcher Beleg liegt vor, welches Bild steht dahinter?","beleg":"Werkstück G.2.1 (Funktion als Hundepfeife); Fn. gl-g-globalisten (Weiß 2024, S. 172; Chapelan 2024, S. 181)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Weder „klar antisemitisch“ noch „völlig neutral“ lässt sich aus dem Wort allein belegen: In solchen Zusammenhängen gilt es als Code, beweist aber keine Absicht. Beide Leser urteilen vor der Prüfung; man fragt, wer gemeint ist und was die Schuldzuweisung stützt.","prueffrage":"Welche Angaben über den Verfasser und den Zusammenhang des Beitrags lagen den beiden Lesern vor, als sie urteilten?","rueckmeldung":[{"option":1,"text":"Dass das Wort als Code bekannt ist, stimmt. Daraus folgt aber noch kein Beleg, dass der Verfasser Juden hasst, und der Text bleibt zu prüfen: Wer ist gemeint, und was stützt die Schuldzuweisung?"},{"option":2,"text":"Eine ausdrückliche Nennung fehlt bei Codes gerade, das ist ihr Zweck und gibt Abstreitbarkeit. Richtig ist: Allein aus dem Wort darf man nichts unterstellen. Ausgeschlossen ist ein antisemitischer Sinn aber nicht; man prüft, wer gemeint ist."},{"option":3,"text":"Als Name für weltweit handelnde Akteure wirkt das Wort harmlos. Hier tragen aber namenlose „Globalisten“ die Schuld an Krise, Pandemie und Kriegen, ein typisches Muster von Verschwörungserzählungen. Ungeprüft abtun hilft da nicht."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3"},{"id":"qx-g-019","clusterId":"G","werkstueckRef":"G.2.1","stufe":4,"question":"Du sollst prüfen, ob dieser Beitrag seine Behauptung belegt. Was ist die zentrale Schwäche seiner Argumentation?","scenario":"Ein Beitrag reiht auf: steigende Energiepreise in Land A, ein Handelsabkommen in Land B, der Rücktritt eines Bankers in Land C – „alles Teil des Plans der Globalisten“. Dass die drei Ereignisse etwas miteinander zu tun haben, wird nirgends gezeigt, nur behauptet.","options":["Aus dem bloßen Nebeneinander verschiedener Ereignisse wird ein gemeinsamer Plan abgeleitet, ohne dass eine Verbindung zwischen ihnen belegt wird.","Die Ereignisse werden einzeln erfunden, weil es weder steigende Energiepreise noch Rücktritte von Bankern geben kann.","Der Beitrag lässt offen, ob es einen Plan gibt, und bleibt deshalb zu vorsichtig, um etwas zu beweisen.","Der Beitrag übersieht, dass in verschiedenen Ländern zwangsläufig immer unterschiedliche Dinge geschehen, weshalb sich ein Plan grundsätzlich nicht erkennen lässt."],"correctIndex":0,"explanation":"Die Schwäche liegt im Schluss, nicht in den Einzelereignissen: Energiepreise, Handelsabkommen und Rücktritte können einzeln durchaus stimmen. Scheinbar unzusammenhängende Handlungen werden hier als Beweis für einen koordinierten Plan gedeutet; das Auge sucht eben Muster, auch im Rauschen (Apophenie). Belegt wäre ein Plan nur durch konkrete, überprüfbare Beweise für eine Absprache. Außerdem bleibt der „Plan der Globalisten“ so vage, dass jedes Ereignis nachträglich als Beweis passt und nichts ihn widerlegen könnte (Unfalsifizierbarkeit durch Vagheit). Gleichzeitigkeit ist noch keine Koordination.","coreRule":"⚡ Gleichzeitigkeit ist keine Koordination: Verlange den Beleg für die Verbindung, nicht nur für die Einzelereignisse.","beleg":"Werkstück G.2.1 (Die rhetorische Funktion: Unfalsifizierbarkeit durch Vagheit; Die transportierten Denkfehler: Apophenie)","status":"entwurf","kurz":"Aus dem Nebeneinander dreier Ereignisse wird ein gemeinsamer Plan, ohne dass eine Verbindung gezeigt wird. Muster sieht man leicht, auch im Rauschen, doch Gleichzeitigkeit ist noch keine Koordination. Erst konkrete Belege für eine Absprache würden tragen.","prueffrage":"Welche Beteiligten haben die drei Ereignisse gemeinsam, und woran ließe sich das nachprüfen?","rueckmeldung":[{"option":1,"text":"Solche Meldungen sind gut vorstellbar: Energiepreise steigen, Banker treten zurück. Die Einzelereignisse können durchaus stimmen. Die Schwäche liegt im Schluss auf einen gemeinsamen Plan, nicht in den Fakten."},{"option":2,"text":"Vorsicht wäre ein Gewinn, doch der Beitrag ist alles andere als zurückhaltend: Er erklärt „alles“ zum Teil eines Plans. Vage ist nur, was dieser Plan sein soll, und gerade das lässt ihn jedes Ereignis aufnehmen."},{"option":3,"text":"Dass in verschiedenen Ländern oft Verschiedenes geschieht, stimmt. Ein Plan ließe sich aber durchaus erkennen, nämlich durch konkrete, überprüfbare Belege für eine Absprache. Genau die fehlen hier."}],"familie":"korrelation-und-ursache","fertigkeit":"F2"},{"id":"qx-g-020","clusterId":"G","werkstueckRef":"G.2.2","stufe":1,"question":"Welcher Denkfehler steckt in dieser Aussage, und welche Gegenfrage deckt ihn am besten auf?","options":["Die Aussage fasst sehr unterschiedliche Redaktionen zu einer einzigen Stimme zusammen (Pauschalisierung). Eine gute Gegenfrage lautet: „Welche konkreten Medien meinst du, und widersprechen sie einander wirklich nie?“","Die Aussage verwechselt Ursache und Wirkung (umgekehrte Kausalität). Eine gute Gegenfrage lautet: „Haben die Medien das Misstrauen erzeugt, oder hat das Misstrauen die Medien erzeugt?“","Die Aussage beruft sich auf eine falsche Autorität (Autoritätsargument). Eine gute Gegenfrage lautet: „Welcher Experte hat dir das so bestätigt?“","Die Aussage schließt von einem Einzelfall auf alle Fälle (Anekdote als Beweis). Eine gute Gegenfrage lautet: „Welches einzelne Erlebnis hat dich zu diesem Urteil gebracht?“"],"correctIndex":0,"explanation":"„Die Medien“ ist ein Sammelbegriff für sehr viele Redaktionen mit unterschiedlichen Eigentümern, Zielgruppen und politischen Ausrichtungen. Wer sie zu einer einzigen, koordinierten Stimme verschmilzt, pauschalisiert und ignoriert Vielfalt und Konkurrenz: Zeitungen wie taz und NZZ oder New York Times und Wall Street Journal vertreten oft gegensätzliche Positionen. Die Gegenfrage zwingt zur Konkretisierung und macht die Behauptung überprüfbar. Dass einzelne Artikel Fehler enthalten können, ist damit nicht bestritten; es ist aber etwas anderes als eine pauschale Gleichschaltung aller Medien. Ein Pauschalurteil lässt sich nicht widerlegen, ein konkreter Fall dagegen schon.","coreRule":"⚡ „Die Medien“ gibt es nicht als eine Stimme, sondern als viele, die einander widersprechen.","beleg":"Werkstück G.2.2 (Die rhetorische Funktion, Punkt 3: Schaffung eines Strohmanns)","status":"entwurf","scenario":"Bei einem Familientreffen kommt das Gespräch auf Nachrichten. Ein Verwandter sagt: „Die Medien lügen doch alle dasselbe, die sind gleichgeschaltet.“","kurz":"„Die Medien“ sind viele Redaktionen mit unterschiedlichen Eigentümern und Positionen, keine einheitliche Stimme. Wer sie zusammenwirft, ignoriert Vielfalt und Konkurrenz. Die Nachfrage nach konkreten Medien macht die Behauptung überprüfbar.","prueffrage":"Nennt der Verwandte für sein Urteil eine Quelle, ein Erlebnis oder eine Ursache, oder nur das Urteil selbst?","rueckmeldung":[{"option":1,"text":"Dass Misstrauen und Berichterstattung sich gegenseitig beeinflussen können, klingt plausibel. Die Aussage behauptet aber gar keine Ursache-Wirkung-Beziehung, sondern verschmilzt viele Redaktionen zu einer einzigen Stimme."},{"option":2,"text":"Nach der Quelle einer Behauptung zu fragen, ist oft sinnvoll. Hier beruft sich aber niemand auf eine Autorität, die Behauptung bleibt pauschal. Die Frage nach einem Experten lässt offen, wer mit „die Medien“ überhaupt gemeint ist."},{"option":3,"text":"Pauschalurteile entstehen tatsächlich oft aus einzelnen Erfahrungen, und der Anlass könnte aufschlussreich sein. Er bleibt aber unbekannt, und der Kern liegt anderswo: Viele verschiedene Redaktionen werden als eine einheitliche Stimme behandelt."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3"},{"id":"qx-g-021","clusterId":"G","werkstueckRef":"G.2.2","stufe":2,"question":"Welcher Denkfehler steckt in der Art, wie dein Onkel Meldungen bewertet?","scenario":"Dein Onkel sagt über Zeitungen und Fernsehsender: „Das stand in der Zeitung, also gelogen.“ Eine Meldung, die sein Weltbild stützt, lässt er dagegen als „seltene Ausnahme von gutem Journalismus“ gelten. Meldungen, die ihm widersprechen, wertet er als weiteren Beweis dafür, dass „die Lügenpresse“ eben lügt.","options":["Er hält Meldungen nur für wahr oder gelogen und lässt keinen Raum für Irrtümer, Fehler und Zwischenstufen.","Er schließt von einer einzelnen Falschmeldung auf alle Meldungen derselben Zeitung und prüft die übrigen nicht einzeln.","Er macht die Zeitungen zur einzigen Ursache aller gesellschaftlichen Probleme und übersieht andere Einflüsse.","Er wertet Meldungen danach, ob sie zu seinem Weltbild passen, nicht nach ihrem Inhalt."],"correctIndex":3,"explanation":"Der Onkel bewertet nicht den Inhalt einer Meldung, sondern nur, ob sie zu seinem Weltbild passt. Passende Meldungen gelten selbst dann als glaubwürdig, wenn sie aus derselben Quelle stammen, nur als „seltene Ausnahme“. Widersprechende Meldungen zählen als zusätzlicher Beweis für seine Sicht. So bestätigt jede Nachricht sein Weltbild, und keine kann es mehr korrigieren. Das ist ein Bestätigungsfehler. Ein pauschales Etikett wie „Lügenpresse“ verstärkt ihn, weil es als Filter wirkt: Es macht die Prüfung des einzelnen Artikels überflüssig. Dass er die Zeitungen als Ganzes verwirft, statt Meldungen zu prüfen, erinnert zwar an ein Ad hominem. Der Kern seines Fehlers ist aber, dass er je nach Weltbild unterschiedlich misst. Auch ein Monokausaler Fehlschluss liegt nicht vor, denn der Onkel benennt in seinen Sätzen keine Ursachen für gesellschaftliche Probleme. Sinnvoll ist es, auf Spezifität zu bestehen: Welcher Artikel enthält welche überprüfbare Falschaussage, und wurde sie später korrigiert?","coreRule":"⚡ Wenn jede Nachricht danach gewertet wird, ob sie ins Weltbild passt, ist das keine Prüfung, sondern ein Filter.","beleg":"Werkstück G.2.2 (Die transportierten Denkfehler: Bestätigungsfehler)","status":"entwurf","kurz":"Der Onkel bewertet nicht den Inhalt einer Meldung, sondern ob sie zu seinem Weltbild passt. Deshalb bestätigt jede Nachricht seine Sicht und keine kann sie korrigieren. Das ist ein Bestätigungsfehler, den ein Etikett wie „Lügenpresse“ noch verstärkt.","prueffrage":"Was haben die Meldungen gemeinsam, die der Onkel gelten lässt, und aus welchen Quellen stammen sie?","rueckmeldung":[{"option":0,"text":"Dass er nur „wahr“ oder „gelogen“ kennt, zeigt sich in seinen Sätzen tatsächlich. Sein Maßstab wechselt aber je nach Weltbild: Passende Meldungen gelten als gut, andere als Lüge. Das Problem ist die ungleiche Messung, nicht die grobe Einteilung."},{"option":1,"text":"Einzeln prüft er tatsächlich nicht. Von einer einzelnen Falschmeldung, von der er verallgemeinert, ist aber nirgends die Rede, und passende Meldungen derselben Quellen lässt er sogar gelten: Er misst je nach Weltbild unterschiedlich."},{"option":2,"text":"Von gesellschaftlichen Problemen und ihren Ursachen spricht der Onkel gar nicht; es geht allein darum, wie er Meldungen bewertet. Eine Alleinursache für irgendetwas benennt er nirgends."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5"},{"id":"qx-g-022","clusterId":"G","werkstueckRef":"G.2.2","stufe":3,"question":"Ein Bekannter sagt, ein Pauschalvorwurf wie „Lügenpresse“ sei doch bloß ein derber Ausdruck für Medienkritik und deshalb unproblematisch. Was ist die stärkste Gegenüberstellung?","options":["Der Ausdruck verwirft alle Medien pauschal, statt einen konkreten Fehler zu benennen, und er war schon im Ersten Weltkrieg ein nationalistischer Kampfbegriff.","Der Ausdruck ist zu derb für eine sachliche Debatte, weil er einzelne Journalistinnen und Journalisten persönlich beleidigt und verletzt.","Der Ausdruck ist zwar zu allgemein, aber ohne historischen Hintergrund, weil er erst in den letzten Jahren als Schlagwort aufkam.","Der Ausdruck wird von den Redaktionen selbst gern benutzt, um jede Kritik an ihrer Arbeit lächerlich zu machen und abzuwehren."],"correctIndex":0,"explanation":"Berechtigte Medienkritik benennt einen konkreten Artikel, einen überprüfbaren Fehler und fragt, ob er korrigiert wurde. Ein Pauschalbegriff wie „Lügenpresse“ leistet das nicht: Er verwirft alle Quellen auf einmal und macht jede Gegeninformation von vornherein verdächtig. Dazu kommt die Herkunft des Wortes. Es ist älter als der Nationalsozialismus und war spätestens im Ersten Weltkrieg ein nationalistischer Kampfbegriff gegen die Presse. Die NS-Propaganda griff ihn auf und spitzte ihn antisemitisch zu, etwa gegen eine „jüdisch marxistische Lügenpresse“. Nach 1945 verschwand er weitgehend und wurde ab Oktober 2014 im Umfeld von Pegida wiederbelebt. Die Jury der Aktion „Unwort des Jahres“ wählte ihn im Januar 2015 zum Unwort des Jahres 2014, weil er Medien pauschal diffamiere und die für die Demokratie nötige Pressefreiheit gefährde, und verwies dabei ausdrücklich auf die NS-Vorgeschichte. Der Einwand „Das hat mit früher nichts zu tun“ ist also sachlich falsch. Auch ein bloßes „zu derb“ trifft den Kern nicht: Das Problem liegt in der Generalanklage statt in der Kritik an konkreten Fehlern.","coreRule":"⚡ Ein Kampfbegriff hat eine Geschichte: Wer ihn benutzt, ruft sie mit auf.","beleg":"Werkstück G.2.2 (Historische Anknüpfung); Fn. gl-g-1 (Unwort des Jahres 2014, Jury-Begründung vom 13.01.2015; Begriffsgeschichte: Schmitz-Berning 2007, S. 327)","status":"entwurf","scenario":"Beim Abendessen verteidigt ein Bekannter den Ausdruck „Lügenpresse“: „Das ist halt zugespitzte Kritik. Wer Medien kritisiert, muss auch mal deutlich werden dürfen. Das hat doch mit früher nichts zu tun.“","kurz":"„Lügenpresse“ verwirft alle Medien auf einmal, statt einen überprüfbaren Fehler zu benennen, und das Wort war schon im Ersten Weltkrieg ein nationalistischer Kampfbegriff. „Hat mit früher nichts zu tun“ stimmt also nicht.","prueffrage":"Seit wann ist „Lügenpresse“ als Schlagwort belegt, und wer hat es damals gegen wen benutzt?","rueckmeldung":[{"option":1,"text":"Derb ist der Ausdruck, aber darin liegt nicht das Hauptproblem. Er richtet sich nicht gegen einzelne Personen, sondern verwirft die Presse insgesamt, ohne einen überprüfbaren Fehler zu nennen."},{"option":2,"text":"Dass der Ausdruck zu allgemein ist, stimmt. Ein neues Schlagwort ist er aber nicht: Er ist älter als der Nationalsozialismus und wurde ab Oktober 2014 im Umfeld von Pegida wiederbelebt."},{"option":3,"text":"Hier sind die Rollen vertauscht: Der Begriff wird gegen die Presse gerichtet, nicht von Redaktionen benutzt. Sein Problem ist, dass er jede Gegeninformation von vornherein verdächtig macht, statt konkrete Fehler zu benennen."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-g-023","clusterId":"G","werkstueckRef":"G.2.2","stufe":4,"question":"Du sollst einschätzen, ob die Antwort des Sprechers berechtigte Medienkritik oder pauschale Delegitimierung ist. Welche Prüfung führt am besten zu einem begründeten Urteil?","scenario":"Nach einem Produktrückruf berichten mehrere Zeitungen kritisch über ein Unternehmen. Dessen Sprecher erklärt: „Das ist alles gekaufte Hetzpresse, da ist kein Wort wahr.“ Ein Artikel nennt einen konkreten Mangel mit Chargennummer, ein anderer enthält eine Zahl, die das Unternehmen für falsch hält.","options":["Man prüft, ob die Kritik in ruhigem, höflichem Ton vorgetragen wird, denn sachliche Kritik erkennt man an ihrer Form.","Man prüft, ob der Kritiker selbst journalistisch gearbeitet hat und die Branche aus eigener Erfahrung kennt.","Man prüft, ob ein konkreter Artikel mit überprüfbarer Falschaussage benannt wird und ob die Redaktion diese später korrigierte.","Man prüft, ob die Kritik mehrere Medien zugleich trifft, denn Vorwürfe gegen einzelne Häuser sind legitim, gegen mehrere nicht."],"correctIndex":2,"explanation":"Berechtigte Kritik hat eine Adresse: Welcher Artikel, wann, welche überprüfbare Falschaussage, und wurde sie korrigiert? Das lässt sich nachprüfen und im Zweifel widerlegen. Der Pauschalvorwurf „gekaufte Hetzpresse“ verwirft dagegen eine ganze Quelle wegen ihrer angeblichen Zugehörigkeit statt den einzelnen Beitrag zu prüfen, ein Ad Hominem. Jede Kritik, die von dort kommt, lässt sich dann als Bestätigung des eigenen Weltbildes abtun. Journalistische Fehler und Tendenzen zu leugnen wäre ebenso falsch; entscheidend ist die Spezifität. Ton, Berufserfahrung und die Zahl betroffener Medien sagen nichts über die Richtigkeit einer einzelnen Aussage; dafür braucht es den konkreten Beleg.","coreRule":"⚡ Kritik an Medien hat eine Adresse: Artikel, Datum, Aussage, Korrektur.","beleg":"Werkstück G.2.2 (Das Anti-Denkmuster; Ad Hominem)","status":"entwurf","kurz":"Berechtigte Kritik hat eine Adresse: Sie benennt Artikel und überprüfbare Falschaussage, und man kann nachsehen, ob korrigiert wurde. „Gekaufte Hetzpresse“ verwirft dagegen alle kritischen Berichte auf einmal, auch den mit Chargennummer, statt einen einzelnen zu prüfen.","prueffrage":"Wie lautet die Zahl, die das Unternehmen für falsch hält, und welche Zahl nennt es selbst?","rueckmeldung":[{"option":0,"text":"Ein ruhiger Ton wirkt seriös und macht Kritik angenehmer. Über die Richtigkeit sagt er aber nichts: Auch ein höflich vorgetragener Vorwurf kann falsch sein, ein scharfer kann stimmen. Entscheidend bleibt, ob sich die einzelne Aussage belegen lässt."},{"option":1,"text":"Wer die Branche kennt, kann Hinweise geben, wo Fehler typischerweise entstehen. Ob eine bestimmte Aussage stimmt, entscheidet das aber nicht, denn dafür zählt der Beleg und nicht der Beruf des Kritikers."},{"option":3,"text":"Ob ein Vorwurf ein Haus oder mehrere trifft, macht ihn weder berechtigt noch unberechtigt. Mehrere Redaktionen können denselben Fehler übernehmen oder zugleich zu Recht berichten, etwa über einen Mangel mit Chargennummer."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3"},{"id":"qx-g-024","clusterId":"G","werkstueckRef":"G.2.3","stufe":1,"question":"Du liest in einem Forum: „Meine Heilpraktikerin sagt, die Schulmedizin behandelt nur Symptome, wir setzen auf ganzheitliche Heilung.“ Du fragst dich, ob das Wort „Schulmedizin“ hier neutral beschreibt oder etwas anderes tut. Woran erkennst du am besten, dass es hier als Kampfbegriff eingesetzt wird?","options":["Das Wort wird abwertend gebraucht und stellt die Medizin als starres System dar, damit die eigene Methode als überlegene Alternative erscheint.","Das Wort stammt aus der Fachsprache und wird von einer Laiin benutzt, die die Nuancen medizinischer Begriffe nicht kennen kann.","Das Wort wird in einem Gesundheitsforum benutzt und ist deshalb automatisch ein Kampfbegriff, der die eigene Berufsgruppe über andere stellt.","Das Wort wird verwendet, obwohl es in Versicherungsverträgen steht, und schließt dadurch bestimmte Behandlungen vom Leistungskatalog aus."],"correctIndex":0,"explanation":"Überprüfe, wie das Wort gebraucht wird, nicht das Wort selbst: Wer „Schulmedizin“ abwertend verwendet (hier: „behandelt nur Symptome“) und die wissenschaftsbasierte Medizin als starres System darstellt, um die eigene Methode als überlegene Alternative zu positionieren, nutzt das Wort als Kampfbegriff. Dass das Wort allgemein gebräuchlich ist und sogar in Versicherungsbedingungen vorkommt, zeigt nur, dass es auch neutral verwendet werden kann. Darauf kommt es an: Wer spricht mit welcher Absicht, und was soll durch den Kontrast erreicht werden? Das bloße Vorkommen des Wortes, ob eine Laiin oder eine Fachkraft spricht, der Ort, an dem es fällt, oder seine Verwendung in Verträgen machen es noch nicht zum Kampfbegriff.","coreRule":"⚡ Entscheidend ist nicht das Wort, sondern wer es mit welcher Absicht abwertend einsetzt.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Einleitung und Punkt 3: Implizite Abwertung; Abschluss-Diagnose des Pathologen)","status":"entwurf","scenario":"Das Wort „Schulmedizin“ ist im Deutschen allgemein gebräuchlich, es steht sogar in den Musterbedingungen privater Krankenversicherungen.","kurz":"Entscheidend ist, wie das Wort gebraucht wird: Wer „Schulmedizin“ als starres System abwertet („behandelt nur Symptome“), um die eigene Methode als überlegen darzustellen, nutzt es als Kampfbegriff. Dass das Wort an sich auch neutral vorkommt, ändert daran nichts.","prueffrage":"Welche Eigenschaften schreibt der Forumsbeitrag jeder der beiden Behandlungsarten zu?","rueckmeldung":[{"option":1,"text":"Ob jemand Laie oder Fachkraft ist, sagt wenig darüber, ob ein Wort als Kampfbegriff dient. Auch seine Herkunft entscheidet das nicht, zumal das Wort im Alltag längst allgemein gebräuchlich ist. Maßgeblich ist, wie und wozu es gebraucht wird."},{"option":2,"text":"Ein Forum bringt oft Streit mit sich, doch der Ort macht ein Wort nicht zum Kampfbegriff; dort kann es ebenso neutral fallen. Erst der abwertende Gebrauch mit erkennbarer Absicht, hier der Aufwertung der eigenen Methode, macht den Unterschied."},{"option":3,"text":"Das Vorkommen in Versicherungsbedingungen zeigt nur, dass das Wort auch neutral gebraucht wird. Mit dem Leistungskatalog hat der Satz im Forum nichts zu tun; zum Kampfbegriff macht das Wort erst die Abwertung der anderen Medizin."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-g-025","clusterId":"G","werkstueckRef":"G.2.3","stufe":2,"question":"Welche Antwort entkräftet die Behauptung am besten?","scenario":"Eine Bekannte sagt: „Die Schulmedizin hat seit hundert Jahren nichts dazugelernt, ich bleibe bei sanften Alternativen.“ Du möchtest ihr sachlich antworten, ohne sie bloßzustellen.","options":["Die Medizin ist tatsächlich träge, aber gerade diese Vorsicht und Langsamkeit macht ihre Verlässlichkeit aus.","Die Medizin prüft ihre Annahmen systematisch und ändert sie, wenn Studien dagegensprechen: Theorien werden verworfen, Behandlungen verbessert.","Die Medizin lernt dazu, aber vor allem durch Anregungen aus der Alternativmedizin, die sie nach und nach in ihre Lehrbücher übernimmt.","Die Medizin lernt nur bei Medikamenten dazu; ihre Grundannahmen sind seit der Antike im Wesentlichen unverändert."],"correctIndex":1,"explanation":"Die Behauptung „hat nichts dazugelernt“ ist eine Tatsachenbehauptung und lässt sich prüfen: Medizinische Lehrmeinungen werden regelmäßig revidiert, wenn bessere Studien vorliegen, und Behandlungen werden laufend verbessert. Das Wort „Schule“ weckt zwar das Bild von Auswendiglernen und Dogma, beschreibt aber eine Medizin, die es so nicht gibt, ein klassischer Strohmann. Die Antwort, die der Medizin Trägheit zugesteht, räumt den Stillstandsvorwurf unnötig ein. Die Antworten, die Übernahmen aus der Alternativmedizin oder unveränderte Grundannahmen seit der Antike behaupten, stellen Dinge als Tatsache hin, die sich nicht belegen lassen oder falsch sind. Eine gute Entgegnung widerlegt den Stillstandsvorwurf mit dem, was die Sache tatsächlich auszeichnet: systematische Selbstkorrektur.","coreRule":"⚡ Prüfe, ob das Wort ein Bild erzeugt, das nicht zur Sache passt: „Schule“ suggeriert Stillstand, doch die Medizin korrigiert sich ständig selbst.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Punkt 1: Schaffung eines Strohmanns)","status":"entwurf","kurz":"Der Vorwurf, die Medizin habe nichts dazugelernt, ist eine prüfbare Tatsachenbehauptung. Er stimmt nicht, denn ihre Annahmen werden systematisch getestet und bei Gegenbefunden geändert. Wer Trägheit zugesteht, räumt ihn unnötig ein.","prueffrage":"Welche Behandlung von vor hundert Jahren wird heute noch genauso angewendet, und welche nicht mehr?","rueckmeldung":[{"option":0,"text":"Vorsicht bei neuen Befunden ist tatsächlich ein Qualitätsmerkmal. Der Vorwurf des Stillstands bleibt aber stehen, wenn du ihn zugestehst, obwohl er nicht stimmt: Es wird laufend dazugelernt und revidiert."},{"option":2,"text":"Der Satz kommt der Bekannten entgegen und wirkt versöhnlich. Dass die Medizin vor allem durch Anregungen aus der Alternativmedizin lernt, lässt sich aber nicht belegen: Geändert wird, was Studien widerlegen, gleich woher eine Idee stammt."},{"option":3,"text":"Dass sich bei Medikamenten viel getan hat, stimmt. Auch die Grundannahmen haben sich aber stark verändert: Die antike Säftelehre etwa wurde verworfen, Keimtheorie und Hygiene kamen hinzu. Damit stützt die Antwort den Vorwurf sogar."}],"familie":"wertende-woerter-abziehen","fertigkeit":"F2"},{"id":"qx-g-026","clusterId":"G","werkstueckRef":"G.2.3","stufe":4,"question":"Was ist an dieser Rahmung der Debatte problematisch?","scenario":"Eine Zeitung kündigt eine Debatte an: „Schulmedizin gegen Alternativmedizin“ – zwei Gäste, je fünf Minuten Redezeit, kein Hinweis darauf, was Studien zur Wirksamkeit der jeweiligen Methoden zeigen.","options":["Sie ist fair, denn in einer offenen Gesellschaft müssen alle Behandlungsansätze gleich viel Redezeit erhalten, damit das Publikum selbst entscheidet.","Sie ist nur wegen der kurzen Redezeit ein Problem, denn mit mehr Zeit wären beide Seiten gleichwertig vertreten.","Sie ist problematisch, denn Alternativmedizin darf in Medien nie vorkommen, sodass schon ein Gast zu viel ist.","Sie erzeugt eine falsche Ausgewogenheit, denn der Unterschied zwischen nachgewiesener und fehlender Wirksamkeit verschwindet."],"correctIndex":3,"explanation":"Die Gegenüberstellung zweier Gäste mit gleicher Redezeit suggeriert zwei gleichwertige, konkurrierende Schulen oder Philosophien. Das ist falsche Ausgewogenheit: Gleich viel Raum täuscht gleich viel Beleg vor. In der Realität gibt es Methoden, die ihre Wirksamkeit nach wissenschaftlichen Standards nachgewiesen haben, und Methoden, bei denen das nicht gelungen ist. Das ist ein Unterschied in der Beweislage, keine Frage der Weltanschauung. Auch das Wort „Schulmedizin“ in dieser Gegenüberstellung hilft nicht, denn es macht aus wissenschaftsbasierter Medizin eine bloße Denkschule unter mehreren. Daraus folgt nicht, dass Alternativmedizin nie besprochen werden darf. Falsch ist die Rahmung „zwei gleichwertige Seiten“, nicht das Thema.","coreRule":"⚡ Zwei Gäste sind noch keine zwei gleichwertigen Positionen: Frag nach der Evidenz hinter jeder Seite.","beleg":"Werkstück G.2.3 (Die rhetorische Funktion, Punkt 2: Etablierung einer falschen Symmetrie)","status":"entwurf","kurz":"Zwei Gäste mit gleicher Redezeit suggerieren zwei gleichwertige Schulen, obwohl sich die Beweislage unterscheidet: Gleich viel Raum täuscht gleich viel Beleg vor. Das Thema selbst darf besprochen werden, nur die Rahmung trägt nicht.","prueffrage":"Welche Gründe nennt die Ankündigung dafür, gerade diese beiden Seiten mit gleicher Redezeit gegenüberzustellen?","rueckmeldung":[{"option":0,"text":"Alternativmedizin öffentlich zu diskutieren ist in einer offenen Gesellschaft durchaus legitim. Gleiche Redezeit sagt aber nichts über die Belege: Sie lässt zwei gleich gut gestützte Positionen vermuten, obwohl die Beweislage verschieden ist."},{"option":1,"text":"Mehr Zeit würde den Fehler nicht beheben, denn er steckt in der Gegenüberstellung selbst. Je länger zwei Gäste gleichberechtigt auftreten, desto stärker wirkt es, als stünden zwei gleich gut belegte Positionen gegeneinander."},{"option":2,"text":"Dass die Debatte problematisch ist, stimmt, doch der Grund ist ein anderer. Alternativmedizin darf durchaus besprochen werden, etwa mit offener Auskunft darüber, was Studien zeigen. Falsch ist die Rahmung als gleichwertige Seiten."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2"},{"id":"qx-g-027","clusterId":"G","werkstueckRef":"G.2.4","stufe":1,"question":"Welche Antwort prüft die Behauptung am besten, ohne berechtigte Kritik an Konzernen wegzuwischen?","options":["Du fragst nach, welches Unternehmen oder welche Praktik konkret gemeint ist, und ob sich daraus auf alle Ärzte schließen lässt.","Du stimmst zu, dass Ärzte beeinflusst sind, und rätst, sich künftig nur noch auf eigene Recherche zu verlassen.","Du widersprichst: Misstrauen gegenüber großen Konzernen ist unbegründet, und die Behauptung hat keinen wahren Kern.","Du erklärst, dass die Pharmaindustrie aus vielen Unternehmen besteht und der Begriff deshalb nicht passt, und die Behauptung damit hinfällig ist."],"correctIndex":0,"explanation":"Misstrauen gegenüber großen, mächtigen Konzernen ist eine gesunde demokratische Haltung, denn die Pharmaindustrie ist ein profitorientiertes System mit nachgewiesenen Fehlverhaltensweisen. Der Denkfehler liegt erst in der pauschalen Verallgemeinerung: Aus berechtigter Kritik an einzelnen Missständen wird die Ablehnung der gesamten wissenschaftsbasierten Medizin und der individuellen Integrität vieler Ärzte und Forscher. Die Rückfrage nach dem konkreten Unternehmen oder Missstand erkennt den wahren Kern an und macht zugleich sichtbar, ob sich die Aussage überhaupt belegen lässt. Wer die Sorge pauschal abtut, verliert das Gespräch; wer ihr pauschal zustimmt, übernimmt den Fehlschluss; und wer nur den Begriff als falsch abtut, geht der eigentlichen Frage aus dem Weg.","coreRule":"⚡ Misstrauen ist ein Werkzeug, es braucht aber eine Adresse, sonst wird es zum Pauschalurteil.","beleg":"Werkstück G.2.4 (Das Adaptive Talent; Der Kipppunkt; Kontext & Tiefe)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Ich traue keinem Arzt mehr, die sind doch alle von Big Pharma gekauft.“ Du willst weder so tun, als gäbe es keine Interessenkonflikte in der Industrie, noch die Pauschalaussage einfach stehen lassen.","quote":"","quoteLabel":"","kurz":"Die Rückfrage nach dem konkreten Unternehmen oder Missstand nimmt den berechtigten Kern ernst und zeigt zugleich, ob sich die Aussage belegen lässt. Der Denkfehler liegt erst darin, aus Kritik an einzelnen Missständen ein Urteil über alle Ärzte zu machen.","prueffrage":"Wie viele Ärzte kennt die Person persönlich, und von wie vielen weiß sie, dass sie Geld von Herstellern bekommen?","rueckmeldung":[{"option":1,"text":"Interessenkonflikte gibt es tatsächlich, und einzelne Ärzte lassen sich beeinflussen. Daraus folgt aber nicht, dass alle betroffen sind. Wer pauschal zustimmt und zur reinen Eigenrecherche rät, übernimmt die Verallgemeinerung, statt sie zu prüfen."},{"option":2,"text":"Die Pauschale ist tatsächlich zu grob. Misstrauen gegenüber mächtigen Konzernen ist aber berechtigt, denn es gibt nachgewiesenes Fehlverhalten. Wer allen Verdacht abtut, verliert das Gespräch, weil der wahre Kern unbeachtet bleibt."},{"option":3,"text":"Der Sammelbegriff ist wirklich ungenau, denn die Industrie besteht aus vielen Unternehmen. Der Streit um das Wort ändert aber nichts an der Sorge dahinter und lässt die Frage offen, ob und wo es tatsächlich Missstände gibt."}],"familie":"kritik-braucht-adresse","fertigkeit":"F3"},{"id":"qx-g-028","clusterId":"G","werkstueckRef":"G.2.4","stufe":2,"question":"Welche Antwort nimmt die Sorge ernst und regt zugleich zur Differenzierung an?","scenario":"Jemand sagt: „Ich traue keinem Arzt mehr, die sind doch alle von Big Pharma gekauft.“ Du möchtest das Gespräch offen halten.","options":["„Das ist ein Mythos: Die Industrie nimmt keinen Einfluss auf die Medizin, dafür gibt es keinen einzigen Beleg.“","„Da hast du recht: Am besten vertraust du nur Ärzten, die nie Kontakt zur Industrie oder ihren Studien hatten.“","„Industrieeinfluss gibt es, dafür gibt es dokumentierte Fälle. Sind wirklich alle gekauft, oder meinst du bestimmte Praktiken?“","„Dein Misstrauen ist irrational: Es gibt Studien, die den Nutzen belegen, also gibt es keinen Grund für Zweifel.“"],"correctIndex":2,"explanation":"Der Vorwurf enthält einen wahren Kern: Die Pharmaindustrie ist ein profitorientiertes System mit nachgewiesenen Fehlverhaltensweisen (ein gut dokumentiertes Beispiel ist der Vioxx-Skandal). Genau deshalb scheitern die anderen Antworten: Wer den Einfluss leugnet oder das Misstrauen als irrational abtut, nimmt die Sorge nicht ernst und verliert das Gegenüber. Wer pauschal zustimmt oder jeden Kontakt zur Industrie zum Ausschlusskriterium macht, übernimmt die undifferenzierte Verallgemeinerung. Hilfreich ist, den berechtigten Teil anzuerkennen und dann zu fragen, ob der Vorwurf für Millionen einzelner Ärzte und Forscher gilt oder für bestimmte, benennbare Praktiken. So wird aus dem Pauschalurteil eine prüfbare Behauptung.","coreRule":"⚡ Nimm das Misstrauen ernst und frag nach dem Unterschied zwischen einzelnen Praktiken und Millionen von Menschen.","beleg":"Werkstück G.2.4 (Werkbank-Frage; Kontext & Tiefe)","status":"entwurf","kurz":"Der Vorwurf hat einen wahren Kern, Industrieeinfluss ist dokumentiert, taugt aber nicht als Pauschalurteil über alle Ärzte. Wer die Sorge anerkennt und dann nach benennbaren Praktiken fragt, macht daraus eine prüfbare Behauptung und hält das Gespräch offen.","prueffrage":"Wie reagiert jemand mit dieser Sorge vermutlich, wenn man ihm sagt, es gebe keinen Grund zum Zweifel?","rueckmeldung":[{"option":0,"text":"Wer Einfluss rundweg bestreitet, wirkt, als wolle er den Streit gewinnen. Es gibt aber dokumentierte Fälle wie Vioxx; die Antwort ist daher selbst falsch und nimmt die Sorge nicht ernst."},{"option":1,"text":"Die Sorge ernst zu nehmen ist richtig, doch hier wird auch die Verallgemeinerung übernommen. Ein Ausschluss jeder Industrienähe wäre kaum umsetzbar und prüft nichts darüber, wer sich tatsächlich unredlich verhält."},{"option":3,"text":"Dass es Studien mit belegtem Nutzen gibt, stimmt, beantwortet den Vorwurf aber nicht: Fehlverhalten in einzelnen Fällen bleibt möglich. Misstrauen als „irrational“ abzutun, beendet zudem eher das Gespräch."}],"familie":"berechtigten-kern-anerkennen","fertigkeit":"F3"},{"id":"qx-g-029","clusterId":"G","werkstueckRef":"G.2.4","stufe":3,"question":"Was ist an dieser Reaktion problematisch?","scenario":"Eine Studie zu einem neuen Medikament wurde vom Hersteller finanziert. Ein Bekannter sagt: „Industriestudie – kann man vergessen.“","options":["Er hat recht: Wegen des Interessenkonflikts sind industriefinanzierte Studien grundsätzlich unbrauchbar und sollten ignoriert werden.","Er hat unrecht: Herstellerstudien werden vorab von Aufsichtsbehörden auf Fehler geprüft und sind deshalb immer verlässlich.","Er hat nur dann unrecht, wenn er selbst Arzt ist, weil nur dann sein Urteil über Studien fundiert genug ist.","Er verwirft die Studie allein wegen der Finanzierung, ohne Methodik und Ergebnisse geprüft zu haben."],"correctIndex":3,"explanation":"Eine Finanzierung durch den Hersteller ist ein berechtigter Anlass, genauer hinzusehen: Wer von einem Ergebnis profitiert, hat einen Anreiz zur Schönfärberei. Die Herkunft des Geldes sagt aber noch nichts darüber, ob die Studie sauber gemacht wurde; das zeigt sich erst an Methodik und Ergebnissen. Wer jede industriefinanzierte Studie automatisch für ungültig erklärt, verwechselt Misstrauen mit Prüfung und urteilt über die Quelle statt über die Sache. Weitet man dieses Muster aus und tut ganze Forschungsfelder als „gekaufte Wissenschaft“ ab, kann es im Extremfall dazu führen, dass Menschen wirksame Behandlungen ablehnen. Entscheidend ist die Prüfung, nicht das Etikett.","coreRule":"⚡ Wer die Studie bezahlt hat, ist eine Frage an die Methode, kein Urteil über das Ergebnis.","beleg":"Werkstück G.2.4 (Red Flags; Kontext & Tiefe: Delegitimierung der Wissenschaft)","status":"entwurf","kurz":"Wer wegen der Finanzierung genauer hinsieht, handelt vernünftig. Wer die Studie allein deshalb verwirft, ersetzt die Prüfung durch ein Etikett: Ob sie sauber gemacht ist, zeigt sich erst an Methodik und Ergebnissen.","prueffrage":"Wie viele Teilnehmende hatte die Studie, gab es eine Vergleichsgruppe, und wer hat die Daten ausgewertet?","rueckmeldung":[{"option":0,"text":"Der Interessenkonflikt ist ein echter Grund, genauer hinzusehen. Daraus folgt aber nicht, dass man die Studie ignorieren darf: Ob sie sauber gemacht ist, zeigt sich erst an Methodik und Ergebnissen, nicht an der Geldquelle."},{"option":1,"text":"Dass der Bekannte zu pauschal urteilt, stimmt. Die Gegenposition ist aber genauso pauschal: Nicht jede Herstellerstudie wird vorab von einer Behörde geprüft, und auch eine geprüfte ist nicht „immer“ verlässlich."},{"option":2,"text":"Ob die Reaktion problematisch ist, hängt nicht vom Beruf des Bekannten ab, sondern davon, ob er Methodik und Ergebnisse angesehen hat. Fachwissen erleichtert die Prüfung, ersetzt sie aber nicht; auch ein Arzt kann nur nach der Finanzierung urteilen."}],"familie":"inhalt-statt-absender","fertigkeit":"F2"},{"id":"qx-g-030","clusterId":"G","werkstueckRef":"G.2.4","stufe":4,"question":"Welcher Schritt in dieser Argumentation trägt nicht?","scenario":"Ein Beitrag schildert den gut dokumentierten Vioxx-Skandal: Ein Pharmaunternehmen hielt Hinweise auf Herzrisiken seines Schmerzmittels zu lange zurück. Daraus folgert der Beitrag: „Also unterdrückt die ganze Branche längst Heilmittel gegen Krebs.“","options":["Ein belegter Einzelfall eines Unternehmens wird zum Beweis für ein verdecktes Vorgehen der ganzen Branche erklärt.","Ein realer Skandal dient als Beispiel, obwohl belegte Fälle von Fehlverhalten nichts über die Branche aussagen können.","Der Skandal wird zu knapp dargestellt, obwohl erst eine vollständige Aufarbeitung zeigen würde, ob die Branche betroffen ist.","Ein einzelnes Unternehmen wird kritisiert, obwohl Kritik an einzelnen Firmen nicht berechtigt ist, solange die Branche Nutzen stiftet."],"correctIndex":0,"explanation":"Die Branche hat einen wahren Kern, den man nicht wegreden muss: Sie ist profitorientiert, und es gibt nachgewiesenes Fehlverhalten. Ein belegter Missstand eines Unternehmens ist deshalb legitime Kritik. Der Fehler liegt im Sprung: Ein Einzelfall belegt den Einzelfall. Dass die ganze Branche Heilmittel gegen Krebs unterdrückt, folgt daraus nicht. Der reale Skandal dient hier als Hebel für die viel größere Verschwörungserzählung, dass „Big Pharma“ Heilmittel unterdrückt.","coreRule":"⚡ Ein belegter Einzelfall trägt nur den Einzelfall, nicht ein ganzes System.","beleg":"Werkstück G.2.4 (Kontext & Tiefe; Anwendung & Relevanz: In Verschwörungsmythen; Schmiede-Übung)","status":"entwurf","kurz":"Vioxx ist ein belegter Missstand und legitime Kritik, aber er belegt nur diesen Fall. Der Fehler liegt im Sprung von einem Unternehmen auf die ganze Branche und auf eine große Behauptung wie die unterdrückten Krebsmittel.","prueffrage":"Was genau zeigt der Vioxx-Fall, und was davon hat mit Krebsmitteln zu tun?","rueckmeldung":[{"option":1,"text":"Dass ein Einzelfall nicht die ganze Branche belegt, stimmt. Belegte Fälle sagen aber sehr wohl etwas aus: Vioxx zeigt echtes Fehlverhalten eines Unternehmens. Was nicht trägt, ist der Sprung von diesem Fall auf alle."},{"option":2,"text":"Eine ausführlichere Darstellung würde an der Lücke nichts ändern, denn der Skandal gilt als gut dokumentiert. Selbst eine vollständige Aufarbeitung zeigte nur, was in diesem Fall geschah, nichts über Krebsmittel in der ganzen Branche."},{"option":3,"text":"Daran, einen Missstand bei einer einzelnen Firma zu kritisieren, ist nichts auszusetzen, denn belegtes Fehlverhalten bleibt Kritik wert. Dass die Branche insgesamt Nutzen stiftet, macht sie nicht unantastbar. Der Mangel liegt im Schluss aufs Ganze."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1"},{"id":"qx-g-031","clusterId":"G","werkstueckRef":"G.3.1","stufe":1,"question":"Du prüfst die Werbung. Welche Rückfrage deckt am besten auf, ob die Rede von „Toxinen“ und „Schlacken“ überhaupt etwas Konkretes behauptet?","options":["Welche Studie über Saftkuren ist die größte, und wie viele Teilnehmende hatte sie?","Wie heißt jeder gemeinte Stoff chemisch, und wie wurde seine Menge vor und nach der Kur gemessen?","Wie viele Menschen haben die Kur schon gekauft, und wie zufrieden waren sie damit?","Welche Zutaten stecken in den Säften, und welche davon sind natürlichen Ursprungs?"],"correctIndex":1,"explanation":"Die Wörter klingen nach Wissenschaft, benennen aber keine bestimmte Substanz. „Toxin“ stammt aus der Toxikologie und wird hier zum Sammelbegriff für alles Unbestimmte, was als schädlich empfunden wird. „Schlacken“ stammt aus der Metallurgie und ist auf den Körper übertragen worden; biologisch gibt es sie nicht. Eine Behauptung ohne benennbaren Stoff lässt sich weder messen noch widerlegen. Die Rückfrage nach Name und Messung zwingt die Werbung, Konkretes zu liefern. Die anderen Fragen lassen offen, ob es das angebliche Problem überhaupt gibt: Zufriedenheitsberichte sind rein subjektive Eindrücke, Verkaufszahlen zeigen nur Nachfrage, und „natürlich“ sagt nichts über Wirkung; keine dieser Angaben benennt einen Stoff oder eine Messung. Die Frage nach der größten Studie setzt voraus, dass es Belege gibt, und prüft nicht, was behauptet wird. Tatsächlich fand eine Übersichtsarbeit von 2015 für kommerzielle Detox-Diäten keine überzeugenden Belege, weder für die Ausscheidung von Toxinen noch für Gewichtsmanagement.","coreRule":"⚡ Ein Begriff, der sich nicht chemisch benennen lässt, beschreibt keine Substanz, sondern ein Gefühl.","beleg":"Werkstück G.3.1 (Kontext & Tiefe: Pseudowissenschaftliche Umdeutung; Fn. gl-g-detox, Klein/Kiat 2015)","status":"entwurf","scenario":"Eine Werbeanzeige für eine „Detox-Saftkur“ verspricht, „Toxine und Schlacken“ auszuleiten, die sich durch Umwelt und Ernährung im Körper angesammelt hätten. Welche Stoffe genau gemeint sind, steht nirgends.","kurz":"„Toxine“ und „Schlacken“ klingen nach Wissenschaft, benennen aber keinen bestimmten Stoff und lassen sich so weder messen noch widerlegen. Erst die Frage nach Name und Messung zwingt die Werbung, Konkretes zu liefern.","prueffrage":"Welchen einzigen Stoff aus der Anzeige könntest du morgen im Labor suchen lassen?","rueckmeldung":[{"option":0,"text":"Studien sind für Wirkversprechen wichtig. Die Frage setzt aber schon voraus, dass klar ist, was die Anzeige behauptet. Solange kein Stoff benannt ist, weiß man nicht, wonach eine Studie überhaupt hätte suchen sollen."},{"option":2,"text":"Viele zufriedene Kundinnen und Kunden klingen nach einem Beleg. Verkaufszahlen zeigen aber nur Nachfrage, und Zufriedenheit ist ein Eindruck. Ob dabei ein bestimmter Stoff ausgeleitet wurde, sagen beide nicht."},{"option":3,"text":"Die Zutaten zu kennen ist nützlich, und natürliche Säfte sind nicht grundsätzlich bedenklich. „Natürlich“ sagt aber nichts über eine Wirkung, und weder ein Stoff noch eine Messung kommt dabei vor. Die Frage nach den „Toxinen“ bleibt offen."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-g-032","clusterId":"G","werkstueckRef":"G.3.1","stufe":2,"question":"Was folgt aus deiner Beobachtung für die Behauptung, die Kur habe Giftstoffe aus deinem Körper ausgeleitet?","scenario":"Nach drei Tagen einer teuren Detox-Saftkur fühlst du dich leichter und „reiner“. Du hast dafür bezahlt, du glaubst an die Wirkung, und du hast drei Tage lang kaum etwas gegessen. Du fragst dich, ob dein gutes Gefühl beweist, dass die Kur Giftstoffe ausgeleitet hat.","options":["Nichts Verlässliches: Das Gefühl ist subjektiv und kann durch Erwartung entstehen, es zeigt nicht, welcher Stoff ausgeleitet wurde.","Es spricht für die Wirkung: Wer sich besser fühlt, hatte vorher unbemerkt Schadstoffe angesammelt, die jetzt fehlen.","Es zeigt eine Entlastung: Leber und Nieren konnten durch die Kur besser arbeiten, was das Wohlbefinden hebt.","Es belegt die Wirkung, wenn das Gefühl lange anhält: Eine bloße Einbildung würde nach Wochen verfliegen."],"correctIndex":0,"explanation":"Ein gutes Gefühl ist ein schwacher Beleg: Wer Geld für eine Kur ausgibt und an sie glaubt, fühlt sich oft schon deshalb besser (Erwartungs- bzw. Placebo-Effekt). Dazu kommt, dass du drei Tage kaum etwas gegessen hast, und wer wenig isst, fühlt sich oft schon dadurch leichter. Um eine Ausleitung zu zeigen, müsste man den Stoff benennen und seine Konzentration vor und nach der Kur messen; ein Gefühl, auch ein lang anhaltendes, leistet das nicht. Schädliche Substanzen baut vor allem die Leber ohnehin ständig ab, und die Nieren scheiden viele davon aus. Eine Übersichtsarbeit von 2015 (Klein/Kiat) fand zu kommerziellen Detox-Diäten keine randomisierten kontrollierten Studien am Menschen und keine überzeugende Evidenz für die Ausleitung von Toxinen.","coreRule":"⚡ Ein gutes Gefühl nach einer Kur belegt nicht, dass ein Gift ausgeleitet wurde: Dafür braucht es einen benannten Stoff und eine Messung davor und danach.","beleg":"Werkstück G.3.1 (Red Flags; Verbindungen: Placebo); Fn. gl-g-detox (Klein/Kiat 2015, J Hum Nutr Diet 28(6), S. 675–686)","status":"entwurf","kurz":"Ein gutes Gefühl ist ein schwacher Beleg: Erwartung, der bezahlte Preis und drei Tage fast ohne Essen können es auch ohne Ausleitung erklären. Um eine Ausleitung zu zeigen, müsste man einen Stoff benennen und seine Konzentration vor und nach der Kur messen.","prueffrage":"Was hast du in den drei Tagen außer den Säften anders gemacht als sonst, und wie fühlt sich das gewöhnlich an?","rueckmeldung":[{"option":1,"text":"Ein gutes Gefühl scheint einen Grund zu brauchen, und Schadstoffe, die jetzt fehlen, wären einer. Dass sie vorher da waren, ist aber genau das, was erst zu belegen wäre; Erwartung und drei Tage fast ohne Essen können das Gefühl ebenso erklären."},{"option":2,"text":"Leber und Nieren entgiften tatsächlich: Die Leber baut Schadstoffe ständig ab, die Nieren scheiden viele davon aus. Dass die Kur sie entlastet, wird aber nur aus dem guten Gefühl geschlossen und ist weder gemessen noch belegt."},{"option":3,"text":"Einbildung müsste nach Wochen verfliegen, so scheint es; doch auch Erwartungseffekte können lange anhalten. Ein Gefühl bleibt subjektiv, benennt keinen Stoff und ersetzt keine Messung vor und nach der Kur."}],"familie":"begriff-messbar-machen","fertigkeit":"F1"},{"id":"qx-g-033","clusterId":"G","werkstueckRef":"G.3.1","stufe":3,"question":"Bei wem wird aus einer harmlosen Angewohnheit ein echtes Problem?","options":["Ein Mann trinkt drei Tage nur Säfte, weil er sich danach leichter fühlt, und kehrt dann zu seiner normalen Ernährung zurück.","Eine Frau hat seit Stunden Erbrechen und Krämpfe nach einem Pilzgericht und setzt auf eine Detox-Kur statt auf ärztliche Hilfe.","Eine Studentin gibt für die Kur mehr Geld aus als geplant und ärgert sich, weil sie nach drei Tagen vor allem hungrig war.","Ein Läufer trinkt „Detox“-Smoothies, weil er den Geschmack mag, und nimmt an, dass sie sein Wohlbefinden steigern."],"correctIndex":1,"explanation":"Entscheidend ist nicht, ob jemand Geld ausgibt, ob ein Produkt wissenschaftlich klingt oder ob eine Kur unwirksam ist, sondern was sie ersetzt. Eine Saftkur, die man macht, weil man sich danach besser fühlt, bleibt meist harmlos: Das Gefühl ist echt, die behauptete „Entgiftung“ nicht, aber der Schaden ist gering. Gefährlich wird es, wenn ein unwirksames Produkt an die Stelle wirksamer Hilfe tritt. Bei einer realen Vergiftung zählt jede Stunde, und ein Produkt ohne nachgewiesene Wirkung über die von Leber und Nieren hinaus kostet dann Zeit, die für eine echte Behandlung fehlt. Ärger über Geld oder Hunger ist ein Verbraucherproblem, kein Gesundheitsrisiko.","coreRule":"⚡ Harmlos ist das Ritual, gefährlich ist der Ersatz für echte Behandlung.","beleg":"Werkstück G.3.1 (Der Kipppunkt)","status":"entwurf","scenario":"Vier Personen nutzen „Detox“-Produkte, deren Anbieter versprechen, „Schlacken“ und Giftstoffe aus dem Körper auszuleiten.","kurz":"Ein unwirksames Produkt wird dann gefährlich, wenn es wirksame Hilfe ersetzt: Bei Verdacht auf Pilzvergiftung zählt jede Stunde. Entscheidend ist nicht, ob Geld fließt oder die Kur unwirksam ist, sondern was sie verdrängt.","prueffrage":"Was hätte jede der vier Personen ohne die Kur stattdessen getan, und was hätte ihr das gebracht?","rueckmeldung":[{"option":0,"text":"Drei Tage nur Säfte wirken extrem, und die versprochene „Entgiftung“ ist unbelegt. Doch die Kur ist kurz, das gute Gefühl danach ist echt, und sie verdrängt keine wirksame Hilfe; der Schaden bleibt meist gering."},{"option":2,"text":"Dass die Kur teuer war und vor allem hungrig machte, ist ärgerlich und spricht gegen das Produkt. Ein Gesundheitsrisiko entsteht daraus aber nicht, denn es wird keine wirksame Hilfe verdrängt. Das ist ein Verbraucherproblem."},{"option":3,"text":"Ob die Smoothies das Wohlbefinden wirklich steigern, ist unbelegt, und eine „Entgiftung“ leisten sie nicht. Doch wer sie wegen des Geschmacks trinkt, verzichtet auf nichts Wichtiges. Unwirksam heißt noch nicht gefährlich."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4"},{"id":"qx-g-034","clusterId":"G","werkstueckRef":"G.3.1","stufe":4,"question":"Mit welchem einfachen Versuch prüfst du am besten, ob die Verfärbung wirklich ausgeleitete Giftstoffe zeigt?","scenario":"Eine Werbung verspricht: Ein Detox-Fußpflaster zieht über Nacht Giftstoffe aus dem Körper, am Morgen ist es dunkel verfärbt. Als „Beweis“ wird die braune Verfärbung gezeigt. Viele dieser Pflaster enthalten getrockneten Holzessig, der Feuchtigkeit anzieht.","options":["Das Pflaster zwei Nächte statt einer tragen: Hellt es sich in der zweiten Nacht wieder auf, sind die Giftstoffe ausgeleitet.","Ein unbenutztes Pflaster trocken und kühl lagern: Färbt es sich trotzdem, hat es vorher schon jemand getragen oder berührt.","Die Farbe mit Pflastern anderer Marken vergleichen: Je dunkler das Pflaster ausfällt, desto mehr Gift hat es aufgenommen.","Ein unbenutztes Pflaster befeuchten und Wärme aussetzen: Verfärbt es sich auch ohne Fuß, beweist die Farbe nichts."],"correctIndex":3,"explanation":"Ein guter Test widerlegt nicht einfach die Behauptung, sondern baut eine einfache Alternativerklärung und prüft sie: Wenn die Verfärbung auch ohne Körper entsteht, kann sie kein Beleg für ausgeleitete Giftstoffe sein. Der Gegenversuch ist leicht durchführbar: ein paar Tropfen Wasser auf ein unbenutztes Pflaster, eine Tasse heißen Tee darauf stellen und zehn Minuten warten. Ein Pflaster, das sich beim zweiten Tragen aufhellt, oder ein Marken-Vergleich der Dunkelheit sagt nichts über Gift im Körper, und Trockenlagerung klärt nicht, ob Feuchtigkeit die Ursache ist.","coreRule":"⚡ Baue die einfachste Alternativerklärung und teste sie, bevor du an eine Entgiftung glaubst.","beleg":"Werkstück G.3.1 (Werkbank-Frage; Red Flags); Fn. gl-g-6 (Goldacre 2008, Bad Science, Kap. 1 „Matter“)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Verfärbt sich ein Pflaster auch ohne Fuß, wenn es nur Feuchtigkeit und Wärme abbekommt, kann die Farbe keine ausgeleiteten Giftstoffe belegen. Wer die Verfärbung als Beweis nimmt, übersieht diese einfache Alternativerklärung.","prueffrage":"Welche Zutat des Pflasters könnte sich über Nacht auch ohne Giftstoffe verfärben, und wodurch?","rueckmeldung":[{"option":0,"text":"Wird das Pflaster wieder heller, wirkt das wie ein Zeichen, dass etwas aufgebraucht ist. Solange nicht geklärt ist, wodurch es sich überhaupt färbt, sagt ein Farbwechsel aber nichts über Gift im Körper."},{"option":1,"text":"Ein unbenutztes Pflaster als Kontrolle zu nehmen, ist ein guter Ansatz. Trockene Lagerung prüft aber nicht, ob Feuchtigkeit die Farbe auslöst. Bleibt die Verfärbung aus, wäre die nächstliegende Alternativerklärung gar nicht getestet."},{"option":2,"text":"Marken zu vergleichen wirkt wie eine Messung. Daraus folgt aber nicht, dass die Farbe Gift anzeigt: Sie kann von der Zusammensetzung abhängen, und „dunkler heißt mehr Gift“ wird nur vorausgesetzt, nicht belegt."}],"familie":"fair-testen","fertigkeit":"F1"},{"id":"qx-g-035","clusterId":"G","werkstueckRef":"G.3.2","stufe":1,"question":"Ein Homöopath sagt: „Wasser hat ein Gedächtnis. Ein Tropfen Ursubstanz hinterlässt in der Verdünnung seine Information, und die wirkt dann heilend.“ Welcher Einwand trifft die Behauptung am stärksten?","options":["Hätte Wasser ein perfektes Gedächtnis, trüge es auch die Informationen aus seiner ganzen früheren Geschichte; warum es sich nur an die letzte erinnern soll, bleibt unerklärt.","Wasser kann Informationen nur kurz behalten, sodass die Wirkung eines Mittels schon nach wenigen Minuten wieder verschwinden würde.","Wasser aus Kläranlagen ist stärker belastet als Quellwasser und eignet sich deshalb schlechter als Träger für die Information eines Mittels.","Ein Gedächtnis des Wassers kann nur in sehr verdünnten Lösungen entstehen und ist bei stärkeren Konzentrationen nicht mehr messbar."],"correctIndex":0,"explanation":"Das Wasser der Erde ist seit Jahrmillionen im Kreislauf und hatte unzählige Kontakte. Wer behauptet, es „erinnere“ sich ausgerechnet an die letzte „Information“ und vergesse alle anderen, muss einen Mechanismus nennen, der das Vergessen steuert; ohne ihn gilt die Behauptung nur für den einen Fall, den man gerade braucht. Der Einwand zur Dauer zielt physikalisch in eine richtige Richtung, denn Strukturen im flüssigen Wasser ordnen sich in Billionstelsekunden um, nicht erst nach Minuten; so formuliert räumt er aber ein, dass Wasser überhaupt Informationen speichert. Verschmutzung und Konzentration sind Nebenpunkte. Den Kern trifft nur der Widerspruch in einem Gedächtnis, das nichts vergisst und doch gezielt eine einzige Information trägt.","coreRule":"⚡ Ein Gedächtnis, das nichts vergisst, kann nicht gezielt eine einzige Information tragen.","beleg":"Werkstück G.3.2 (Die Wasserleiche; Aktivierungs-Frage)","status":"entwurf","scenario":"Das Wasser, aus dem ein homöopathisches Mittel hergestellt wird, war schon im Ozean, im Körper von Dinosauriern, in Kläranlagen, in Wolken, in Pflanzen und im Blut von Menschen. Es hat also unzählige Kontakte hinter sich. Jetzt wird es mit einem Tropfen Ursubstanz „informiert“.","kurz":"Hätte Wasser ein Gedächtnis, das nichts vergisst, trüge es die Spuren seiner ganzen Geschichte. Dass es nur die letzte „Information“ behält, braucht einen Mechanismus des Vergessens, und ohne den gilt die Behauptung nur dort, wo man sie braucht.","prueffrage":"Wie viele Stoffe hat dasselbe Wasser vor dem Tropfen schon berührt, und welche davon spielen in der Behauptung eine Rolle?","rueckmeldung":[{"option":1,"text":"Die Dauer ist ein ernster Punkt: Strukturen im Wasser ordnen sich sogar in Billionstelsekunden um. So formuliert räumt der Einwand aber ein, dass Wasser Informationen aufnimmt, und übergeht den Widerspruch, dass es auch alles Frühere tragen müsste."},{"option":2,"text":"Verschmutztes Wasser klingt tatsächlich nach schlechtem Träger. Doch auch Quellwasser hat eine lange Vorgeschichte voller Kontakte. Der Einwand löst das Kernproblem nicht und übernimmt die Annahme, Wasser könne Informationen speichern."},{"option":3,"text":"Dass nur bestimmte Verdünnungen wirken sollen, klingt nach einer plausiblen Bedingung. Es ist aber eine unbelegte Zusatzannahme und erklärt nicht, warum die frühere Geschichte des Wassers nicht stört. Der Kern der Behauptung bleibt unberührt."}],"familie":"zu-ende-denken","fertigkeit":"F1"},{"id":"qx-g-036","clusterId":"G","werkstueckRef":"G.3.2","stufe":2,"question":"Welches Ergebnis dieser Wiederholung würde die Behauptung „Wasser speichert Information“ am stärksten untergraben?","scenario":"Ein Bekannter verweist dich auf eine Veröffentlichung in „Nature“ von 1988. Ein französischer Forscher berichtete dort, stark verdünnte Antikörper wirkten noch auf weiße Blutzellen, und das soll belegen, dass Wasser ein „Gedächtnis“ hat. In seinem Labor wurde der Versuch anschließend wiederholt, diesmal mit Proben, deren Inhalt die Auswertenden nicht kannten (verblindet).","options":["Der Effekt tritt auch bei verblindeter Auswertung zuverlässig auf, nur eine physikalische Erklärung fehlt noch.","Der Effekt verschwindet, sobald die Auswertenden nicht wissen, welche Probe welche ist.","Der Effekt tritt auf, ist aber so klein, dass er für die Praxis kaum eine Rolle spielt.","Der Effekt lässt sich nicht prüfen, weil verblindete Versuche bei hohen Verdünnungen nicht möglich sind."],"correctIndex":1,"explanation":"Wenn ein Effekt nur auftritt, solange die Auswertenden die Proben kennen, liegt die Ursache nahe bei den Erwartungen der Beobachter und nicht beim Wasser. Genau so verlief der Fall: Der Biomediziner Jacques Benveniste meldete 1988 in „Nature“ Effekte extrem verdünnter Antikörper auf weiße Blutzellen, doch bei der Nachprüfung in seinem Labor verschwand der Effekt, sobald die Proben verblindet ausgewertet wurden. Ein Befund, der davon abhängt, ob jemand die Probenzuordnung kennt, ist kein belastbarer Beleg für eine Eigenschaft des Wassers. Dagegen würde ein Effekt, der auch verblindet bestehen bleibt, die Behauptung stützen. Ein bloß kleiner Effekt oder eine fehlende Erklärung wären weniger entscheidend, und die Behauptung, Verblindung sei hier unmöglich, ließe sich leicht widerlegen: Man lässt die Proben einfach von jemand anderem codieren.","coreRule":"⚡ Ein Effekt, der verschwindet, wenn niemand weiß, welche Probe welche ist, trägt keine Theorie.","beleg":"Werkstück G.3.2 (Kontext & Tiefe: Unfalsifizierbarkeit); Fn. gl-g-4 (Davenas u. a. 1988, Nature 333, S. 816–818; Maddox/Randi/Stewart 1988, Nature 334, S. 287–290)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Verschwindet ein Effekt, sobald die Auswertenden nicht mehr wissen, welche Probe welche ist, liegt die Ursache nahe bei ihren Erwartungen und nicht beim Wasser. Der Fehler wäre, einen nur unter Kenntnis der Proben gemessenen Effekt als Eigenschaft des Wassers zu werten.","prueffrage":"Mit welchem Ergebnis der Wiederholung wäre zu rechnen, wenn das Wasser in Wahrheit gar nichts speichert?","rueckmeldung":[{"option":0,"text":"Eine noch fehlende Erklärung widerlegt einen Befund tatsächlich nicht. Ein Effekt, der auch verblindet zuverlässig bleibt, würde die Behauptung aber stützen und nicht untergraben."},{"option":2,"text":"Ob ein Effekt praktisch etwas ausmacht, ist eine berechtigte Frage. Sie betrifft aber die Größe und nicht die Echtheit: Ein kleiner, real vorhandener Effekt würde die Behauptung nicht widerlegen."},{"option":3,"text":"Ein Versuch, der sich nicht prüfen ließe, würde nichts gegen die Behauptung zeigen. Zudem stimmt die Annahme nicht: Verblindung ist leicht möglich, indem jemand anderes die Proben codiert, und die Wiederholung wurde ja verblindet durchgeführt."}],"familie":"fair-testen","fertigkeit":"F1"},{"id":"qx-g-037","clusterId":"G","werkstueckRef":"G.3.2","stufe":3,"question":"Was ist an der Antwort des Beraters der entscheidende Denkfehler?","options":["Die Behauptung wird erst nachträglich eingeführt, um den Widerspruch zur fehlenden Substanz abzufangen, und lässt sich mit keinem Instrument prüfen.","Die Behauptung ist unzulässig, weil Wirkungen grundsätzlich nur von Stoffen ausgehen können, die sich mit bloßem Auge erkennen lassen.","Die Behauptung ist widerlegt, weil jedes Wasser seine Struktur dauerhaft behält und deshalb alle Informationen gleichzeitig speichern würde.","Die Behauptung ist zu ungenau, weil der Berater keine Studie nennt, die gezeigt hat, wie viele Moleküle in einer C30-Potenz fehlen."],"correctIndex":0,"explanation":"Die Zusatzannahme „Information im Wasser“ wurde nicht aus Beobachtungen abgeleitet, sondern soll nur den Widerspruch auflösen, dass in stark verdünnten Mitteln (jenseits von etwa C12) kein Molekül der Substanz mehr enthalten ist. Solange diese Information mit keinem Instrument gemessen werden kann, ist die Behauptung unfalsifizierbar. Wo sie doch einmal prüfbar gemacht wurde, hielt sie nicht: Jacques Benveniste meldete 1988 in „Nature“, extrem verdünnte Antikörper wirkten noch auf weiße Blutzellen, doch bei der Nachprüfung verschwand der Effekt, sobald die Proben verblindet ausgewertet wurden. Dazu kommt, dass Wasserstoffbrücken zwischen Wassermolekülen sich im Femto- bis Pikosekundenbereich bilden und lösen, Struktur in Flüssigkeiten ist also extrem kurzlebig. Und warum sollte sich das Wasser ausgerechnet an diese eine Substanz erinnern und alle anderen Stoffe aus seiner langen Geschichte vergessen?","coreRule":"⚡ Eine Zusatzannahme, die nur den Widerspruch abfängt und sich nicht prüfen lässt, ist noch keine Erklärung.","beleg":"Werkstück G.3.2 (Kernidee; Kontext & Tiefe; Verbindungen); Fn. gl-g-5 (Roth 2013, Chemie in unserer Zeit 47, S. 111)","status":"entwurf","scenario":"Eine Kundin fragt in einer Apotheke, wie ein Mittel in der Potenz C30 wirken soll, wenn rechnerisch kein Molekül des Wirkstoffs mehr enthalten ist. Der Berater antwortet: „Das Wasser hat sich die Information gemerkt. Die Wirkung ist eben immateriell.“","kurz":"Die „Information im Wasser“ wird nicht aus Beobachtungen abgeleitet, sondern nachträglich eingeführt, um den Widerspruch zur fehlenden Substanz aufzulösen. Solange sie sich mit keinem Instrument messen lässt, kann sie nichts erklären und nicht widerlegt werden.","prueffrage":"Auf welche Frage der Kundin antwortet der Berater, und welche Beobachtung nennt er als Grundlage für seine Antwort?","rueckmeldung":[{"option":1,"text":"Dass Wirkung nur von Sichtbarem ausgehe, klingt nach nüchterner Vorsicht. Viele Wirkstoffe, Viren und Gase wirken aber, ohne mit bloßem Auge erkennbar zu sein. Der Haken liegt in der nachträglich eingeführten, nicht messbaren Zusatzannahme."},{"option":2,"text":"Hätte Wasser ein Gedächtnis, müsste es sich tatsächlich an alles erinnern. Seine Struktur hält aber nicht dauerhaft, denn Wasserstoffbrücken lösen sich binnen Billionstelsekunden; der Kern ist die nachträglich eingeführte, unprüfbare Annahme."},{"option":3,"text":"Eine Studie zur Molekülzahl braucht es nicht: Dass bei C30 rechnerisch kein Molekül mehr enthalten ist, folgt aus der Verdünnung selbst. Das Problem ist die „Information“, die nur diesen Widerspruch abfangen soll und sich nicht messen lässt."}],"familie":"immunisierung-erkennen","fertigkeit":"F2"},{"id":"qx-g-038","clusterId":"G","werkstueckRef":"G.3.2","stufe":4,"question":"Was ist an dieser Gesprächsführung des Anbieters fehlerhaft?","scenario":"Eine Anzeige für ein „informiertes“ Trinkwassergerät verspricht, es speichere „positive Schwingungen“. Auf die Frage nach einem Messverfahren heißt es: „Die Wirkung ist feinstofflich – du denkst zu materialistisch.“","options":["Er verspricht eine Wirkung, ohne einen prüfbaren Mechanismus zu nennen, und weicht der Nachfrage mit einem Spruch aus.","Er nennt kein einziges Toxin beim Namen, obwohl er ein Gerät zur Wasserreinigung verkauft.","Er deutet an, dass alle kritischen Studien zu seinem Gerät von der Konkurrenz bezahlt seien.","Er teilt die Kundschaft in Erwachte und Schlafende ein und wertet Zweifler pauschal ab."],"correctIndex":0,"explanation":"Eine Wirkbehauptung ist nur dann prüfbar, wenn sie sagt, wie die Wirkung zustande kommen soll und woran man sie messen könnte. „Positive Schwingungen“ werden ohne Speicher- und Abrufmechanismus versprochen und als „feinstofflich“ beschrieben, damit sie sich jeder Messung entziehen. Auf die berechtigte Nachfrage kommt kein Beleg, sondern ein Spruch: „Du denkst zu materialistisch“ ist ein Gedanken-stoppendes Klischee, das die Frage abwürgt, statt sie zu beantworten. Genau diese Antwort ist ein typisches Warnsignal der „Wassergedächtnis“-Rhetorik. Das Muster lässt sich so anwenden: Wer eine Wirkung behauptet, trägt die Beweislast und muss zeigen, wie sich die Wirkung nachweisen lässt. Ohne Mechanismus und Messbarkeit bleibt „Information“ ein Wort ohne Gegenstand. Die anderen Optionen treffen den Kern nicht: Die fehlende Nennung von Toxinen, der Verweis auf bezahlte Studien und die Einteilung in Erwachte und Schlafende kommen in der Anzeige entweder gar nicht vor oder sind höchstens Begleitwirkung. Fehlerhaft im Kern ist, dass Mechanismus und Messbarkeit verweigert und die Behauptung so gegen Prüfung abgeschirmt wird.","coreRule":"⚡ Ohne Mechanismus und Messbarkeit bleibt „Information“ ein Wort ohne Gegenstand.","beleg":"Werkstück G.3.2 (Red Flags)","status":"entwurf","kurz":"Eine Wirkung ist nur prüfbar, wenn gesagt wird, wie sie zustande kommt und woran man sie misst. Hier ersetzt ein Spruch den Beleg, und „feinstofflich“ entzieht die Behauptung jeder Messung, obwohl der Anbieter die Beweislast trägt.","prueffrage":"Woran könnte man hier überhaupt feststellen, ob das Gerät etwas bewirkt oder nicht?","rueckmeldung":[{"option":1,"text":"Bei einem Wassergerät erwartet man vielleicht Aussagen zu Schadstoffen. Die Anzeige verspricht aber keine Reinigung, sondern „positive Schwingungen“. Fehlerhaft ist, dass auf die Frage nach einem Messverfahren nur ein Spruch statt eines Belegs kommt."},{"option":2,"text":"Der Verdacht, Kritik sei gekauft, ist ein bekanntes Ausweichmuster. In diesem Gespräch fällt er aber nicht: Der Anbieter sagt nichts über Studien oder Konkurrenz. Er weicht der Nachfrage nach einem Messverfahren auf andere Weise aus."},{"option":3,"text":"Der Satz „du denkst zu materialistisch“ wertet den Fragenden tatsächlich ab. Das ist aber nur eine Begleiterscheinung: Von Erwachten und Schlafenden ist nicht die Rede. Der Kern liegt darin, dass Mechanismus und Messbarkeit verweigert werden."}],"familie":"mechanismus-verlangen","fertigkeit":"F1"},{"id":"qx-g-039","clusterId":"G","werkstueckRef":"G.3.3","stufe":1,"question":"Du liest die Aussage: „Ich setze auf natürliche Immunität statt auf Impfung.“ Was leistet das Wort „natürlich“ in diesem Satz vor allem?","options":["Es lässt die Infektion als reinen, ursprünglichen Weg erscheinen und blendet die Risiken der Krankheit dabei einfach aus.","Es zeigt an, dass der Weg wissenschaftlich geprüft ist, weil nur unter Alltagsbedingungen erprobte Verfahren als verlässlich gelten.","Es stellt beide Wege als gleichwertig dar, sodass die Wahl nur noch Geschmackssache ist und kein Weg abgewertet wird.","Es verweist auf die lange Entwicklung des Immunsystems und belegt damit, dass eine Infektion den bestmöglichen Schutz liefert."],"correctIndex":0,"explanation":"Das Wort „natürlich“ weckt ein positives Gefühl (Appell an die Natur): Die Infektion wirkt wie ein reiner, ursprünglicher Prozess, die Impfung wie ein künstlicher Eingriff in ein „perfektes“ Immunsystem. Das Narrativ konzentriert sich nur auf das Ergebnis (Immunität) und blendet den Prozess, die potenziell tödliche Krankheit, aus. Dass „natürlich“ nicht „besser“ heißt, zeigt Tetanus: Bei Tetanus führt die Infektion zu keiner Immunität, die Impfung schon. Bei HPV erzeugt die Impfung eine stärkere und verlässlichere Immunantwort als die Infektion. Ob ein Weg gut ist, entscheiden Risiken und Schutz, nicht der Klang des Wortes.","coreRule":"⚡ „Natürlich“ ist ein Gefühlswort und kein Qualitätsnachweis.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Appell an die Natur; Red Flags: Herdenimmunität)","status":"entwurf","scenario":"In einer Diskussion über Impfungen sagt jemand: „Ich setze lieber auf die natürliche Immunität. Das ist der echte Weg, nicht dieser künstliche Eingriff.“","kurz":"„Natürlich“ weckt ein gutes Gefühl: Die Infektion wirkt ursprünglich und rein, die Impfung wie ein Eingriff. So rückt nur das Ergebnis Immunität ins Bild, die möglicherweise gefährliche Krankheit davor verschwindet.","prueffrage":"Wie wirkt der Satz, wenn man „natürliche Immunität“ durch „Immunität nach Ansteckung“ ersetzt?","rueckmeldung":[{"option":1,"text":"Dass „natürlich“ nach Verlässlichkeit klingt, stimmt. Geprüft ist damit aber nichts: Das Wort wirkt über ein Gefühl, nicht über Belege. Ob ein Weg gut ist, entscheiden Risiken und Schutz, nicht der Klang des Wortes."},{"option":2,"text":"Der Satz stellt die Wege nicht gleich, er wertet sie gegeneinander: Die Infektion ist der „echte Weg“, die Impfung ein „künstlicher Eingriff“. Das Wort „natürlich“ verteilt also Lob und Abwertung, statt eine bloße Geschmacksfrage offen zu lassen."},{"option":3,"text":"Das Immunsystem hat sich tatsächlich über lange Zeit entwickelt, doch daraus folgt nicht der beste Schutz durch Infektion. Bei Tetanus bringt die Infektion keine Immunität, die Impfung schon, und bei HPV wirkt die Impfung stärker und verlässlicher."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-g-040","clusterId":"G","werkstueckRef":"G.3.3","stufe":2,"question":"Was ist an dieser Argumentation grundlegend falsch?","scenario":"In einer Diskussion über Impfungen sagt jemand: „Wer Tetanus durchmacht, hat danach natürliche Immunität. Das ist doch der beste Weg, die Impfung brauche ich nicht.“ Du weißt: Das Tetanus-Toxin ist schon in winzigen Mengen tödlich, und eine überstandene Erkrankung hinterlässt keinen Schutz vor einer neuen Ansteckung.","options":["Sie setzt voraus, dass die Erkrankung Schutz hinterlässt; bei Tetanus tut sie das nicht, die Impfung schon, und der „natürliche“ Weg ist hier gefährlicher und nutzlos.","Sie übertreibt, denn die Immunität nach Tetanus ist zwar vorhanden, aber deutlich schwächer und kürzer als nach der Impfung.","Sie ist unvollständig, denn die Immunität entsteht erst nach einer zweiten, deutlich milderen Erkrankung und schützt danach zuverlässig.","Sie ist richtig, denn eine überstandene Krankheit hinterlässt immer robustere Immunität als eine Impfung, und Tetanus ist dafür ein gutes Beispiel."],"correctIndex":0,"explanation":"Das Argument setzt stillschweigend voraus, dass „natürlich“ zugleich „besser“ heißt und dass eine Erkrankung überhaupt Schutz hinterlässt. Beides lässt sich prüfen: Tetanus-Gift ist so stark, dass schon winzige Mengen (geschätzte minimale tödliche Dosis: 2,5 Nanogramm je Kilogramm Körpergewicht) tödlich wirken können. Laut CDC hinterlässt die Erkrankung keine Tetanus-Immunität. Wer sie überlebt, ist deshalb nicht geschützt; nach der Erkrankung soll die Impfung beginnen oder fortgesetzt werden, sobald sich der Zustand stabilisiert hat (CDC). Die Impfung bringt den Schutz, den die Infektion nicht liefert. Bei HPV ist die natürliche Immunität zwar vorhanden, aber schwächer als die Impf-Immunität; bei Tetanus entsteht sie gar nicht. Und „immer robuster“ ist ohnehin zu pauschal: Ob Infektion oder Impfung besser schützt, muss man pro Krankheit prüfen.","coreRule":"⚡ „Natürlich“ heißt nicht „besser“: Prüfe pro Krankheit, ob die Infektion überhaupt schützt, und was der Weg dorthin kostet.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Schaffung einer falschen Sicherheit); Fn. gl-g-2 (CDC, Pink Book, 14. Aufl. 2021, Kap. 21)","status":"entwurf","kurz":"Das Argument setzt stillschweigend voraus, dass eine überstandene Tetanus-Erkrankung schützt. Das tut sie nicht: Der „natürliche“ Weg ist gefährlich und hinterlässt keine Immunität, den Schutz liefert erst die Impfung.","prueffrage":"Was bleibt nach einer überstandenen Tetanus-Erkrankung an Schutz zurück, und wie riskant ist der Weg dorthin?","rueckmeldung":[{"option":1,"text":"Bei manchen Krankheiten, etwa HPV, ist die natürliche Immunität tatsächlich schwächer als die Impf-Immunität. Bei Tetanus entsteht nach der Erkrankung aber gar kein Schutz, nicht bloß ein kürzerer oder schwächerer."},{"option":2,"text":"Auch eine zweite Erkrankung hinterlässt keinen Schutz, und jede ist lebensgefährlich, weil schon winzige Mengen des Gifts tödlich sein können. Wer Tetanus überlebt, ist nicht geschützt und soll mit der Impfung beginnen oder sie fortsetzen."},{"option":3,"text":"Ob Infektion oder Impfung besser schützt, hängt von der jeweiligen Krankheit ab, „immer“ stimmt also nicht. Bei Tetanus passt das Beispiel erst recht nicht: Die Erkrankung hinterlässt keine Immunität, die Impfung schon."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2"},{"id":"qx-g-041","clusterId":"G","werkstueckRef":"G.3.3","stufe":3,"question":"Wie lässt sich der Unterschied zwischen Tetanus und HPV beim Vergleich von „natürlicher“ und Impf-Immunität am genauesten beschreiben?","options":["Bei Tetanus entsteht nach der Krankheit gar kein Schutz, bei HPV ein Schutz, der schwächer und unzuverlässiger ist als der Impfschutz.","Bei beiden Krankheiten entsteht nach der Infektion gar kein Schutz, und der einzige Unterschied liegt in der Schwere der Erkrankung.","Bei Tetanus entsteht nach der Krankheit gar kein Schutz, bei HPV ein Schutz, der stärker und zuverlässiger ist als der Impfschutz.","Bei beiden Krankheiten ist der Schutz nach der Infektion schwächer als der Impfschutz, hält aber deutlich länger an als dieser."],"correctIndex":0,"explanation":"Das Beispiel zeigt, dass es „die“ natürliche Immunität nicht gibt, sondern dass sie je nach Krankheit sehr unterschiedlich ausfällt. Bei Tetanus hinterlässt die Erkrankung laut CDC keine Immunität; der Grund ist die extreme Giftigkeit des Toxins (die geschätzte minimale tödliche Dosis liegt bei 2,5 Nanogramm je Kilogramm Körpergewicht). Deshalb soll auch nach überstandener Krankheit geimpft werden. Bei HPV bildet der Körper nach einer Infektion zwar Antikörper, aber langsam, unvollständig und typspezifisch. Die Impfung erzeugt deutlich höhere Antikörperspiegel (in einer Übersicht 3.000–10.000 mMU/mL gegenüber 100–500 mMU/mL nach natürlicher Ansteckung), und der Impfschutz hält nach bisherigen Daten über ein Jahrzehnt an. „Gar keinen Schutz“ bei HPV zu behaupten wäre übertrieben, „stärker als die Impfung“ wäre falsch. Wer verallgemeinert („immer besser“), übersieht diese Unterschiede zwischen Krankheiten.","coreRule":"⚡ Pauschalaussagen wie „natürlich ist immer besser“ prüfst du Krankheit für Krankheit: Mal fehlt der natürliche Schutz ganz, mal ist er nur schwächer als der Impfschutz.","beleg":"Werkstück G.3.3 (Kontext & Tiefe: Schaffung einer falschen Sicherheit); Fn. gl-g-3 (Ghilencea u. a. 2026, Antibodies 15(4), 61)","status":"entwurf","scenario":"In einer Diskussion sagt jemand: „Natürliche Immunität ist immer besser als eine Impfung.“ Als Gegenargument werden zwei Krankheiten genannt: Tetanus und HPV.","kurz":"Bei Tetanus hinterlässt die Krankheit keinen Schutz, bei HPV nur einen schwachen, langsam aufgebauten und typspezifischen, der an den Impfschutz nicht heranreicht. Der Fehler liegt im „immer“: Natürliche Immunität fällt je nach Krankheit sehr verschieden aus.","prueffrage":"Was bleibt nach überstandener Krankheit jeweils an Schutz zurück, bei Tetanus und bei HPV, und wie verhält sich das zum Impfschutz?","rueckmeldung":[{"option":1,"text":"„Gar kein Schutz“ trifft auf Tetanus zu, ist bei HPV aber übertrieben: Nach einer Infektion bildet der Körper Antikörper, nur langsam und unvollständig. Der Unterschied liegt darin, ob und wie viel Schutz entsteht, nicht in der Schwere."},{"option":2,"text":"Für Tetanus stimmt das, bei HPV ist die Richtung aber vertauscht: Der Schutz nach Ansteckung ist schwächer und unzuverlässiger als der Impfschutz. Ein stärkerer natürlicher Schutz würde „natürlich ist immer besser“ sogar stützen."},{"option":3,"text":"Bei HPV ist der Schutz nach Infektion tatsächlich schwächer als nach Impfung. Bei Tetanus fehlt er aber ganz, und dass natürlicher Schutz länger hält, ist nicht belegt; belegt ist ein Impfschutz gegen HPV über mehr als ein Jahrzehnt."}],"familie":"genau-unterscheiden","fertigkeit":"F1"},{"id":"qx-g-042","clusterId":"G","werkstueckRef":"G.3.3","stufe":4,"question":"Welche Schlussfolgerung ist angemessen?","options":["Der Schutz vor schwerem Verlauf ist hoch, aber gemessen wurde nur bei denen, die die Infektion überlebt haben; Tod und Komplikationen auf dem Weg dorthin sind in der Zahl nicht enthalten.","Der Schutz nach Infektion ist hoch, also ist die Infektion die sicherere Methode, weil sie keine zusätzlichen Risiken mit sich bringt, die man vorher abwägen müsste.","Der Schutz vor erneuter Ansteckung liegt bei nur 45 Prozent, also ist die durchgemachte Infektion wertlos und die Zahlen sprechen klar für die Impfung.","Beobachtungsstudien sind grundsätzlich unbrauchbar, also lässt sich aus den Zahlen über den Schutz nach einer Infektion nichts Sinnvolles ableiten."],"correctIndex":0,"explanation":"Die Zahlen beschreiben den Schutz derjenigen, die die Infektion überlebt haben. Wer daran gestorben ist, taucht in dieser Gruppe nicht auf, und was die erste Erkrankung an Komplikationen gekostet hat, steckt in keiner der Prozentzahlen: Das ist die Perspektive des Überlebensirrtums. Der hohe Schutz vor schwerem Verlauf ist real, wurde aber mit der Krankheit selbst bezahlt, und vor erneuter Ansteckung schützte die Infektion deutlich schlechter. Dass Beobachtungsstudien Störfaktoren enthalten können, mindert die Aussagekraft, macht sie aber nicht wertlos. Wer Wege vergleicht, muss deshalb auch die Kosten des Weges betrachten und nicht nur das Ergebnis am Ziel.","coreRule":"⚡ Ein Schutz, der mit der Krankheit bezahlt wird, ist nicht umsonst, auch wenn er hoch ist.","beleg":"Werkstück G.3.3 (Anwendung & Relevanz: COVID-19-Pandemie; Verbindungen: Überlebensirrtum); Fn. gl-g-reinfektion (COVID-19 Forecasting Team 2023, The Lancet 401, S. 833 und 841)","status":"entwurf","scenario":"Eine Auswertung von 65 Beobachtungsstudien zeigt: Menschen, die eine COVID-19-Infektion überstanden hatten, waren später zu mehr als 78 Prozent vor schwerem Verlauf geschützt, vor erneuter Ansteckung mit Omikron BA.1 aber nur zu rund 45 Prozent. Jemand sagt dazu: „Da seht ihr es: Wer die Krankheit durchmacht, ist hinterher bestens geschützt. Die Impfung brauche ich nicht.“","kurz":"Die Zahlen beschreiben nur den Schutz derer, die die Infektion überstanden haben. Wer daran starb, fehlt in der Gruppe, und Komplikationen der ersten Erkrankung stecken in keiner der Prozentzahlen; über den Preis des Weges sagen sie deshalb nichts.","prueffrage":"Wovor schützte die überstandene Infektion laut den Zahlen gut, wovor weniger gut, und was macht die Person daraus?","rueckmeldung":[{"option":1,"text":"Vor schwerem Verlauf schützte die überstandene Infektion tatsächlich gut. Dass der Weg dorthin ohne Risiko sei, steht aber nicht in den Zahlen: Wer starb, fehlt in der gemessenen Gruppe, und Komplikationen der ersten Erkrankung sind nicht erfasst."},{"option":2,"text":"Mit rund 45 Prozent schützte die Infektion vor erneuter Ansteckung mit Omikron BA.1 deutlich schwächer. Wertlos ist sie deshalb nicht: Vor schwerem Verlauf lag der Schutz über 78 Prozent, und die Impfung kommt in den Zahlen gar nicht vor."},{"option":3,"text":"Beobachtungsstudien können Störfaktoren enthalten, das mindert ihre Aussagekraft. Sie deshalb für „grundsätzlich unbrauchbar“ zu erklären, geht zu weit. Das eigentliche Problem liegt anderswo: Erfasst sind nur die Überlebenden."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4"}]`);export{t as n,n as t};